insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('koeapaschoft-privaten-rechts', 'Köapaschoft privaten Rechts', '', '', '', '', 'Körperschaft privaten Rechts', '[{"kategorie": "allg.", "text": "\"juristische Person, die auf Grundlage privatrechtlicher Bestimmungen gegründet wird und hauptsächlich privaten Interessen dient\""}, {"kategorie": "", "text": "Diese Körperschaften bestehen aus Mitgliedern oder Gesellschaftern und verfolgen in der Regel wirtschaftliche, soziale, kulturelle oder ideelle Ziele"}, {"kategorie": "", "text": "Sie besitzen eine eigene [[Rechtspersönlichkeit]], das heißt, sie können selbstständig Verträge abschließen, Eigentum besitzen und rechtlich vor Gericht auftreten"}, {"kategorie": "", "text": "Merkmale einer Körperschaft privaten Rechts:  (i) Rechtspersönlichkeit: Als juristische Person ist eine Körperschaft privaten Rechts selbst Träger von Rechten und Pflichten, unabhängig von ihren Mitgliedern oder Gesellschaftern;  (ii) Gründungsbasis im Privatrecht: Die Gründung erfolgt durch privatrechtliche Verträge und ist im Allgemeinen nicht an staatliche Genehmigungen gebunden (Ausnahme: Kapitalgesellschaften benötigen eine Eintragung ins Firmenbuch);  (iii) Eigenständige Organe: Körperschaften privaten Rechts besitzen eine interne Organisationsstruktur mit klaren Organen (z. B. [[Vorstand]], [[Aufsichtsrat]], [[Geschäftsführung]]), die für Leitung und Verwaltung zuständig sind;  (iv) Mitgliedschaft oder Gesellschafterprinzip: Die Körperschaft besteht aus Mitgliedern (z. B. in [[Vereinen]]) oder [[Gesellschaftern]] (z. B. in [[Kapitalgesellschaften]]), die an der Zielverfolgung beteiligt sind"}, {"kategorie": "", "text": "Arten von Körperschaften privaten Rechts in Österreich:  (i) [[Vereine]]: Körperschaften, die meist ideelle oder gemeinnützige Ziele verfolgen, wie Sportvereine oder kulturelle Vereinigungen. Die Mitgliedschaft ist in der Regel freiwillig, und sie agieren auf Basis des Vereinsgesetzes;  (ii) [[Kapitalgesellschaften]]: Diese Körperschaften, wie die Aktiengesellschaft (AG) und die Gesellschaft mit beschränkter Haftung (GmbH), dienen wirtschaftlichen Zwecken und haben Gesellschafter, die das Eigenkapital bereitstellen und im Austausch dafür Anteile am Unternehmen besitzen;  (iii) [[Genossenschaften]]: Genossenschaften sind auf Förderung der wirtschaftlichen Interessen ihrer Mitglieder ausgerichtet, wie z. B. landwirtschaftliche oder Wohnbaugenossenschaften;  (iv) [[Stiftungen]]: Stiftungen dienen dazu, ein Vermögen für einen bestimmten Zweck zu verwalten, oft zu gemeinnützigen oder familiären Zwecken, und sind rechtlich eigenständige Körperschaften"}, {"kategorie": "", "text": "Körperschaften privaten Rechts bieten einen rechtlichen Rahmen für die gemeinschaftliche Verfolgung privater und wirtschaftlicher Interessen. Sie ermöglichen es Personen, in organisierten Strukturen zusammenzuarbeiten, Eigenkapital zu bündeln und ihre gemeinsamen Ziele eigenständig und rechtlich abgesichert zu verfolgen. Dies macht sie zu einem wichtigen Bestandteil der österreichischen Wirtschafts- und Gesellschaftsstruktur."}]'::jsonb, ''),
  ('gsoeschoft-mit-beschraenkta-hoftung', 'Gsöschoft mit beschränkta Hoftung', '', '', '', '', 'Gesellschaft mit beschränkter Haftung', '[{"kategorie": "", "text": "Das bedeutet, dass die Gesellschafter im Falle von Verbindlichkeiten des Unternehmens grundsätzlich nur mit dem eingebrachten Gesellschaftskapital und nicht mit ihrem privaten Vermögen haften"}, {"kategorie": "", "text": "Diese Rechtsform ist besonders bei kleinen und mittleren Unternehmen beliebt, da sie eine klare Trennung zwischen Unternehmens- und Privatvermögen bietet und gleichzeitig die Haftung begrenzt"}, {"kategorie": "", "text": "Merkmale einer GmbH:  (i) Beschränkte Haftung: Die Gesellschafter haften nicht persönlich, sondern nur mit ihrer [[Kapitaleinlage]]. Das Mindeststammkapital beträgt in Deutschland beispielsweise 25.000 Euro und in Österreich 35.000 Euro, wobei nur ein Teil davon bei der Gründung eingezahlt werden muss;  (ii) [[Gesellschaftsvertrag]]: Die GmbH wird durch einen Gesellschaftsvertrag (auch [[Satzung]] genannt) gegründet, der notariell beurkundet wird. Dieser Vertrag legt u.a. den Unternehmenszweck, die Höhe des [[Stammkapitals]], die Verteilung der Anteile und die Regelungen zur Gewinnverteilung fest;  (iii) [[Geschäftsführung]]: Die GmbH hat eine oder mehrere Personen als [[Geschäftsführer]], die für das Tagesgeschäft und die Umsetzung der Unternehmensziele verantwortlich sind;  (iv) Die [[Gesellschafterversammlung]] ist das oberste Organ der GmbH und entscheidet über grundlegende Angelegenheiten;  (v) Gewinnverteilung: Gewinne werden entsprechend den Anteilen der [[Gesellschafter]] verteilt, sofern der Gesellschaftsvertrag nichts anderes festlegt;  (vi) Publizitätspflichten: GmbHs unterliegen bestimmten gesetzlichen Offenlegungspflichten, wie etwa der jährlichen Veröffentlichung des [[Jahresabschlusses]] im [[Handelsregister]]"}, {"kategorie": "", "text": "Eine GmbH entsteht rechtlich erst mit der Eintragung ins Handelsregister. Dafür müssen das Mindestkapital nachgewiesen und der Gesellschaftsvertrag erstellt sein. Diese Eintragung macht die GmbH zu einer eigenständigen juristischen Person, die Verträge abschließen und vor Gericht klagen oder verklagt werden kann."}]'::jsonb, ''),
  ('oadentliche-generalvasaummlung', 'Oadentliche Generalvasaummlung', '', '', '', '', 'Ordentliche Generalversammlung', '[{"kategorie": "allg.", "text": "\"regelmäßig, meist jährlich stattfindende Versammlung der Mitglieder oder Aktionäre einer Organsiation, wie z. B. einer [[Aktiengesellschaft]], [[Genossenschaft]] oder eines [[Vereins]]\""}, {"kategorie": "", "text": "Sie dient dazu, über die grundlegenden und routinemäßigen Angelegenheiten der Organisation zu entscheiden und bildet das zentrale Gremium der Mitbestimmung und Kontrolle"}, {"kategorie": "", "text": "In der Ordentlichen Generalversammlung werden in der Regel folgende Angelegenheiten behandelt:  (i) Prüfung und Genehmigung des [[Jahresabschlusses]]: Die Versammlung nimmt den Jahresabschluss entgegen, prüft ihn und stimmt gegebenenfalls über die Genehmigung ab;  (ii) [[Entlastung]] von [[Vorstand]] und [[Aufsichtsrat]]: Die Mitglieder oder Aktionäre entscheiden, ob sie dem Vorstand und gegebenenfalls dem Aufsichtsrat für die geleistete Arbeit im vergangenen Geschäftsjahr die Entlastung erteilen;  (iii) Beschluss über die Gewinnverwendung: Bei Kapitalgesellschaften (z. B. Aktiengesellschaften) wird über die Verwendung des Gewinns abgestimmt, zum Beispiel über die Ausschüttung von [[Dividenden]];  (iv) Wahl und Bestellung von Organen: Die Generalversammlung kann über die Wahl bzw. Wiederwahl von Mitgliedern des Aufsichtsrats oder anderer Kontrollorgane entscheiden;  (v) Bestätigung des Abschlussprüfers: In einigen Fällen wird auch über die Bestätigung oder Wahl des Abschlussprüfers für das kommende Geschäftsjahr abgestimmt;  (vi) Bericht des Vorstands: Der Vorstand informiert die Mitglieder über die Entwicklung und zukünftigen Pläne der Organisation"}, {"kategorie": "", "text": "Die Einberufung erfolgt meist durch den Vorstand, der die Mitglieder oder [[Aktionäre]] fristgerecht und in der vorgeschriebenen Form einlädt. In der Regel erfolgt die Einberufung mit einer Frist von zwei bis vier Wochen"}, {"kategorie": "", "text": "Die Tagesordnungspunkte werden vorab bekannt gegeben, und die Versammlung folgt einem klaren Ablauf, in dem die einzelnen Punkte besprochen und zur Abstimmung gestellt werden."}]'::jsonb, ''),
  ('aussaoadentliche-generalvasaummlung', 'Außaoadentliche Generalvasaummlung', '', '', '', '', 'Außerordentliche Generalversammlung', '[{"kategorie": "allg.", "text": "\"zusätzliche, nicht routinemäßige Versammlung der Mitglieder oder [[Aktionäre]] einer Organisation wie einer [[Aktiengesellschaft]], [[Genossenschaft]] oder eines [[Vereins]]\""}, {"kategorie": "", "text": "Die Außerordentliche Generalversammlung wird einberufen, wenn dringende oder außergewöhnliche Entscheidungen zu treffen sind, die nicht bis zur nächsten [[Ordentlichen]] Generalversammlung warten können"}, {"kategorie": "", "text": "Im Gegensatz zur Ordentlichen Generalversammlung, die jährlich stattfindet und reguläre Themen wie [[Jahresabschluss]] und [[Entlastung]] der Organe behandelt, dient die Außerordentliche Generalversammlung zur Klärung und Entscheidung besonderer Angelegenheiten"}, {"kategorie": "", "text": "Typische Themen einer Außerordentlichen Generalversammlung sind:  (i) Strukturelle Veränderungen: Beschlüsse über [[Fusionen]], [[Übernahmen]] oder die [[Umwandlung]] der Gesellschaft;  (ii) Kapitalmaßnahmen: Entscheidungen über [[Kapitalerhöhungen]] oder [[Kapitalherabsetzungen]];  (iii) Satzungsänderungen: Wichtige Änderungen im [[Gesellschaftsvertrag]] oder der [[Satzung]], die grundlegend für die Organisation sind;  (iii) Wechsel im Führungspersonal: Abberufung oder Bestellung von Mitgliedern im [[Vorstand]] oder [[Aufsichtsrat]];  (iv) Krisenbewältigung: Maßnahmen zur Bewältigung von Krisensituationen, wie drohende [[Insolvenz]] oder große finanzielle Verluste;  (v) Auflösung und Liquidation: Entscheidungsprozesse zur Auflösung der Organisation oder ihrer [[Liquidation]]"}, {"kategorie": "", "text": "Eine Außerordentliche Generalversammlung kann durch verschiedene Organe oder Personengruppen einberufen werden:  (i) Vorstand: Der Vorstand kann die Versammlung einberufen, wenn er es für notwendig hält;  (ii) Aufsichtsrat: Der Aufsichtsrat kann ebenfalls eine außerordentliche Versammlung einberufen, falls dringende Entscheidungen anstehen;  (iii) Minderheitenrecht: In einigen Fällen können auch eine bestimmte Anzahl an Aktionären oder Mitgliedern (oft mindestens 5 %) eine außerordentliche Versammlung verlangen"}, {"kategorie": "", "text": "Die Einberufung erfolgt innerhalb einer bestimmten Frist, die in derà Satzung oder kraft [[Gesetz]] festgelegt ist, und muss eine detaillierte [[Tagesordnung]] enthalten, damit die Teilnehmer sich auf die zu entscheidenden Themen vorbereiten können."}]'::jsonb, ''),
  ('oadentliche-hauptvasaummlung', 'Oadentliche Hauptvasaummlung', '', '', '', '', 'Ordentliche Hauptversammlung', '[{"kategorie": "allg.", "text": "\"regelmäßig, meist jährlich stattfindende Versammlung der Mitglieder oder Aktionäre einer Organsiation, wie z. B. einer [[Aktiengesellschaft]], [[Genossenschaft]] oder eines [[Vereins]]\""}, {"kategorie": "", "text": "Sie dient dazu, über die grundlegenden und routinemäßigen Angelegenheiten der Organisation zu entscheiden und bildet das zentrale Gremium der Mitbestimmung und Kontrolle"}, {"kategorie": "", "text": "In der Ordentlichen Hauptversammlung werden in der Regel folgende Angelegenheiten behandelt:  (i) Prüfung und Genehmigung des [[Jahresabschlusses]]: Die Versammlung nimmt den Jahresabschluss entgegen, prüft ihn und stimmt gegebenenfalls über die Genehmigung ab;  (ii) [[Entlastung]] von [[Vorstand]] und [[Aufsichtsrat]]: Die Mitglieder oder Aktionäre entscheiden, ob sie dem Vorstand und gegebenenfalls dem Aufsichtsrat für die geleistete Arbeit im vergangenen Geschäftsjahr die Entlastung erteilen;  (iii) Beschluss über die Gewinnverwendung: Bei Kapitalgesellschaften (z. B. Aktiengesellschaften) wird über die Verwendung des Gewinns abgestimmt, zum Beispiel über die Ausschüttung von [[Dividenden]];  (iv) Wahl und Bestellung von Organen: Die Generalversammlung kann über die Wahl bzw. Wiederwahl von Mitgliedern des Aufsichtsrats oder anderer Kontrollorgane entscheiden;  (v) Bestätigung des Abschlussprüfers: In einigen Fällen wird auch über die Bestätigung oder Wahl des Abschlussprüfers für das kommende Geschäftsjahr abgestimmt;  (vi) Bericht des Vorstands: Der Vorstand informiert die Mitglieder über die Entwicklung und zukünftigen Pläne der Organisation"}, {"kategorie": "", "text": "Die Einberufung erfolgt meist durch den Vorstand, der die Mitglieder oder [[Aktionäre]] fristgerecht und in der vorgeschriebenen Form einlädt. In der Regel erfolgt die Einberufung mit einer Frist von zwei bis vier Wochen"}, {"kategorie": "", "text": "Die Tagesordnungspunkte werden vorab bekannt gegeben, und die Versammlung folgt einem klaren Ablauf, in dem die einzelnen Punkte besprochen und zur Abstimmung gestellt werden."}]'::jsonb, ''),
  ('parlamentarische-fraktion', 'Parlamentarische Fraktion', '', '', '', '', 'Parlamentarische Fraktion', '[{"kategorie": "pol.", "text": "\"organisierte Gruppe von Abgeordneten im [[Parlament]], die derselben politischen Partei oder einem gemeinsamen politischen Ziel angehören\""}, {"kategorie": "", "text": "Im österreichischen [[Nationalrat]] bilden beispielsweise die Abgeordneten, die für dieselbe Partei gewählt wurden, eine Fraktion"}, {"kategorie": "", "text": "Die Fraktionen sind zentrale Einheiten der politischen Arbeit im Parlament und vertreten geschlossen die Interessen und Positionen ihrer Partei"}, {"kategorie": "", "text": "Wichtige Merkmale und Aufgaben einer Fraktion sind:  (i) Vertretung politischer Positionen: Fraktionen bündeln die Standpunkte und Interessen ihrer Mitglieder, sodass diese als Einheit auftreten und eine gemeinsame Linie verfolgen können;  (ii) Organisation und Koordination der Parlamentsarbeit: Fraktionen bereiten [[parlamentarische]] Initiativen vor, wie z. B. [[Gesetzesvorschläge]] und Anträge, und stimmen ihre Mitglieder auf Abstimmungen ein;  (iii) Stärkung der Durchsetzungskraft: Durch den Zusammenschluss in Fraktionen gewinnen die einzelnen Abgeordneten an Einfluss, da die Fraktion als geschlossenes Gremium mit mehr Gewicht im Parlament auftreten kann;  (iv) Bereitstellung von Ressourcen und Unterstützung: Fraktionen bieten ihren Mitgliedern organisatorische und personelle Unterstützung, z. B. durch Fachreferenten, um die Parlamentsarbeit effizienter zu gestalten;  (v) Verhandlungen und Kompromisse: Fraktionen führen Verhandlungen mit anderen Fraktionen, um politische Kompromisse zu finden oder Mehrheiten für Gesetzesvorhaben zu bilden"}, {"kategorie": "", "text": "In der Regel erhält jede Fraktion im Parlament eine bestimmte Anzahl an Redezeiten und Sitzen in [[Ausschüssen]], die nach der Stärke der jeweiligen Fraktion bemessen wird. Damit spielen Fraktionen eine entscheidende Rolle für die Strukturierung und den Ablauf der parlamentarischen Arbeit und ermöglichen es, die politischen Ziele ihrer Mitglieder wirkungsvoll zu vertreten."}]'::jsonb, ''),
  ('vadeckte-auktion', 'Vadeckte Auktion', '', '', '', '', 'Verdeckte Auktion', '[{"kategorie": "jur.", "text": "\"Auktionsform, bei der die Bieter ihre Gebote geheim abgeben, ohne die Gebote der anderen Teilnehmer zu kennen\""}, {"kategorie": "", "text": "Jeder Bieter reicht nur ein Gebot ein, und der Bieter mit dem höchsten Gebot gewinnt die Auktion"}, {"kategorie": "", "text": "Diese Art der Auktion unterscheidet sich von offenen Auktionen, bei denen die Gebote öffentlich bekannt sind und in Echtzeit aufeinander reagieren"}, {"kategorie": "", "text": "In der Regel kann jeder Bieter nur ein Gebot abgeben, ohne die Möglichkeit, nachträglich zu erhöhen oder zu verändern. Das Gebot ist verbindlich, und der Bieter kann es nicht mehr ändern, nachdem es eingereicht wurde"}, {"kategorie": "", "text": "Verdeckte Auktionen werden häufig bei Ausschreibungen (z. B. für Bauprojekte oder staatliche Aufträge) verwendet, aber auch bei der Versteigerung wertvoller Objekte oder in bestimmten Finanz- und Unternehmensbereichen, wie bei der Vergabe von Unternehmensanteilen"}, {"kategorie": "", "text": "In einigen Fällen gibt es eine zweite Phase, in der die besten Bieter aus der ersten Runde erneut die Möglichkeit haben, ein neues Gebot abzugeben"}, {"kategorie": "", "text": "Da Bieter nicht wissen, welche Gebote die anderen abgeben, müssen sie strategisch abwägen, wie viel sie bereit sind zu bieten, um eine realistische Chance auf den Zuschlag zu haben, ohne übermäßig hoch zu bieten."}]'::jsonb, ''),
  ('hollaendische-auktion', 'Holländische Auktion', '', '', '', '', 'Holländische Auktion', '[{"kategorie": "jur.", "text": "\"Auktionsform, bei der der Preis eines angebotenen Gegenstands schrittweise gesenkt wird, bis ein Bieter bereit ist, den aktuellen Preis zu akzeptieren\""}, {"kategorie": "", "text": "Im Gegensatz zur [[englischen]] Auktion, bei der die Gebote steigen, sinkt der Preis bei einer holländischen Auktion kontinuierlich, und der erste Bieter, der den aktuellen Preis akzeptiert, erhält den Zuschlag und erwirbt den Gegenstand"}, {"kategorie": "", "text": "Diese Art der Auktion wird häufig für den Verkauf von Waren verwendet, bei denen eine schnelle Abwicklung erwünscht ist, z. B. bei verderblichen Gütern wie Blumen (besonders bei Blumenauktionen in den Niederlanden, woher der Name stammt). Sie wird auch für den Verkauf von Finanzinstrumenten oder bei bestimmten Online-Auktionen verwendet"}, {"kategorie": "", "text": "Die Herausforderung für die Bieter besteht darin, abzuschätzen, wie weit der Preis sinken wird, bevor jemand anderes den Zuschlag erhält. Bieter müssen entscheiden, ob sie früh zuschlagen oder riskieren, dass ein anderer Bieter den Gegenstand zu einem niedrigeren Preis erhält."}]'::jsonb, ''),
  ('englische-auktion', 'Englische Auktion', '', '', '', '', 'Englische Auktion', '[{"kategorie": "jur.", "text": "\"gebräuchlichste Form der [[Auktion]], bei der der Preis eines angebotenen Gegenstands in einem offenen Bieterverfahren schrittweise erhöht wird\""}, {"kategorie": "", "text": "Bieter geben ihre Gebote nacheinander ab, wobei jedes neue Gebot höher sein muss als das vorherige"}, {"kategorie": "", "text": "Die Auktion endet, wenn kein Bieter mehr bereit ist, ein höheres Gebot abzugeben, und der Gegenstand wird dem Höchstbietenden durch den Zuschlag des Auktionators verkauft"}, {"kategorie": "", "text": "Englische Auktionen werden häufig in verschiedenen Bereichen eingesetzt, wie z. B. in Auktionshäusern für Kunstwerke, bei Immobilienverkäufen, auf Online-Plattformen wie eBay und bei der Versteigerung von Wertgegenständen."}]'::jsonb, ''),
  ('immateriilles-vamoegn', 'Immateriilles Vamögn', '', '', '', '', 'Immaterielles Vermögen', '[{"kategorie": "jur.", "text": "\"Vermögenswerte, die keinen physischen oder greifbaren Charakter haben, aber dennoch einen wirtschaftlichen Wert darstellen\""}, {"kategorie": "", "text": "Diese Vermögenswerte sind oft mit Rechten, Lizenzen oder geistigem Eigentum verbunden und spielen eine wichtige Rolle in der Bilanzierung von Unternehmen sowie in Erbschafts- und Vermögensaufstellungen"}, {"kategorie": "", "text": "Typische Beispiele für immaterielles Vermögen sind:  (i) Geistiges Eigentum: Dazu gehören Patente, Marken, Urheberrechte und Designs, die dem Inhaber exklusive Rechte an der Nutzung oder Verwertung dieser geschützten Ideen oder Werke gewähren; (ii) Goodwill: Der Geschäftswert, der den Ruf, die Marke, die Kundenbeziehungen oder den Standort eines Unternehmens widerspiegelt und oft bei der Übernahme oder dem Verkauf eines Unternehmens von Bedeutung ist;  (iii) Lizenzen und Nutzungsrechte: Rechtliche Berechtigungen zur Nutzung bestimmter Technologien, Software oder anderer geschützter Produkte, die einem Unternehmen oder einer Person einen wirtschaftlichen Vorteil bieten;  (iv) Software: Eigene oder lizensierte Software, die Unternehmen entwickelt oder nutzt, stellt ebenfalls eine Form von immateriellem Vermögen dar;  (v) Vertragsrechte: Rechte aus langfristigen Verträgen, die wirtschaftliche Vorteile versprechen, z. B. Lieferverträge oder Konzessionen"}, {"kategorie": "", "text": "Immaterielles Vermögen spielt vor allem in der heutigen Wissens- und Dienstleistungsgesellschaft eine zunehmend wichtige Rolle, da es oft einen beträchtlichen Teil des Gesamtwerts von Unternehmen oder Privatpersonen ausmacht."}]'::jsonb, ''),
  ('materiilles-vamoegn', 'Materiilles Vamögn', '', '', '', '', 'Materielles Vermögen', '[{"kategorie": "jur.", "text": "\"alle greifbaren, physischen Vermögenswerte, die einen realen, sichtbaren Wert besitzen und direkt genutzt oder verkauft werden können\""}, {"kategorie": "", "text": "Diese Vermögenswerte sind konkret vorhanden und können physisch gehandhabt oder besessen werden"}, {"kategorie": "", "text": "Typische Beispiele für materielles Vermögen sind:  (i) Immobilien: Grundstücke, Häuser, Wohnungen und andere Gebäude, die zu Eigentum gehören;  (ii) Fahrzeuge: Autos, Motorräder, Boote, Flugzeuge und andere Fortbewegungsmittel;  (iii) Maschinen und technische Geräte: Produktionsanlagen, Büroausstattung, Computer und andere technische Geräte, die für berufliche oder private Zwecke genutzt werden;  (iv) Waren und Vorräte: Lagerbestände, Rohstoffe und Handelswaren, die Unternehmen im Rahmen ihrer Geschäftstätigkeit besitzen;  (v) Möbel und Haushaltsgegenstände: Alle beweglichen Gegenstände im Haushalt, wie Möbel, Schmuck, Kunstwerke und andere physische Besitztümer"}, {"kategorie": "", "text": "Materielles Vermögen ist in der Regel leichter zu bewerten als [[immaterielles]] Vermögen, da es einen direkten Marktwert hat, und spielt sowohl in der privaten Vermögensverwaltung als auch in Unternehmensbilanzen eine zentrale Rolle."}]'::jsonb, ''),
  ('unbewegliches-vamoegn', 'Unbewegliches Vamögn', '', '', '', '', 'Unbewegliches Vermögen', '[{"kategorie": "jur.", "text": "\"Vermögenswerte, die fest mit dem Boden verbunden sind und daher nicht ohne weiteres bewegt oder transportiert werden können\""}, {"kategorie": "", "text": "Es umfasst insbesondere Immobilien und Grundstücke sowie alles, was dauerhaft mit diesen verbunden ist"}, {"kategorie": "", "text": "Typische Beispiele für unbewegliches Vermögen sind:  (i) Grundstücke: Landflächen, die bebaut oder unbebaut sein können;  (ii) Gebäude und Bauwerke: Häuser, Wohnungen, Geschäftshäuser, Fabriken oder andere Bauwerke, die auf einem Grundstück errichtet wurden;  (iii) Dauerhafte Anlagen auf Grundstücken: Dazu gehören auch Bestandteile wie Bäume, Brunnen oder Zäune, die fest mit dem Grundstück verbunden sind;  (iv) Eigentumsrechte an Immobilien: Dazu gehören auch dingliche Rechte wie das [[Wohnungseigentum]], [[Erbbaurechte]] oder [[Wegerechte]]"}, {"kategorie": "", "text": "Unbewegliches Vermögen spielt eine zentrale Rolle im Bereich der Immobilienwirtschaft sowie bei der Vermögensbewertung und im [[Erbrecht]]"}, {"kategorie": "", "text": "Im Gegensatz zu [[beweglichem]] Vermögen hat es oft einen hohen wirtschaftlichen Wert und unterliegt speziellen rechtlichen Regelungen, wie der Eintragung im [[Grundbuch]] und bestimmten Steuer- und Abgabepflichten."}]'::jsonb, ''),
  ('bewegliches-vamoegn', 'Bewegliches Vamögn', '', '', '', '', 'Bewegliches Vermögen', '[{"kategorie": "jur.", "text": "\"alle Vermögenswerte, die körperlich beweglich und nicht fest mit einem Grundstück oder Bauwerk verbunden sind\""}, {"kategorie": "", "text": "Es umfasst also alle Sachen und Rechte, die - im Gegensatz zu [[unbeweglichen]] Vermögenswerten (Immobilien) - relativ leicht transportiert oder verschoben werden können"}, {"kategorie": "", "text": "Typische Beispiele für bewegliches Vermögen sind:  (i) Fahrzeuge: Autos, Motorräder, Boote, Flugzeuge;  (ii) Bargeld und Bankguthaben: Bargeldbestände und Kontoguthaben bei Banken;  (iii) Wertpapiere: Aktien, Anleihen, Investmentfonds;  (iv) Möbel und persönliche Gegenstände: Hausrat, Kunstwerke, Schmuck, technische Geräte;  (v) Waren und Vorräte: Inventar oder Handelsware von Unternehmen"}, {"kategorie": "", "text": "Im Rahmen eines [[Verlassenschaftsverfahrens]] oder einer Vermögensaufstellung wird bewegliches Vermögen neben dem unbeweglichen Vermögen (Immobilien) erfasst, um den Gesamtwert des [[Nachlasses]] oder Vermögens einer Person zu bestimmen."}]'::jsonb, ''),
  ('recht-auf-rechtliches-gehoea', 'Recht auf rechtliches Gehöa', '', '', '', '', 'Recht auf rechtliches Gehör', '[{"kategorie": "jur.", "text": "\"grundlegendes Prinzip im österreichischen [[Verfahrensrecht]], welches gewährleistet, dass jede Person, die von einem gerichtlichen oder behördlichen Verfahren betroffen ist, die Möglichkeit hat, ihre Standpunkte, Argumente und Beweise einzubringen, bevor eine Entscheidung getroffen wird\";  2 Das \"Recht auf rechtliches Gehör\" ist Teil des [[Rechts]] auf ein faires Verfahren und stellt sicher, dass die betroffene Person aktiv am Verfahren teilnehmen und sich zu den relevanten Punkten äußern kann"}, {"kategorie": "", "text": "Wesentliche Aspekte des Rechts auf rechtliches Gehör sind: (i) \nInformation über den Verfahrensstand: Die betroffene Person muss über den Stand des Verfahrens und die gegen sie erhobenen Vorwürfe oder rechtlichen Schritte informiert werden;  (ii) Möglichkeit zur Stellungnahme: Die Person hat das Recht, ihre Sichtweise, Argumente und Beweise einzubringen, bevor das Gericht oder die Behörde eine Entscheidung trifft;  (iii) Recht auf [[Beweisanträge]]: Die betroffene Person darf [[Beweismittel]] vorlegen und beantragen, dass relevante Beweise im Verfahren berücksichtigt werden;  (iv) Einsicht in die Akten: Um eine fundierte Stellungnahme abzugeben, hat die betroffene Person das Recht, die Verfahrensakten einzusehen, um alle relevanten Informationen zu kennen;  (v) Recht auf Anhörung: In vielen Verfahren hat die betroffene Person das Recht, persönlich gehört zu werden, insbesondere wenn dies entscheidend für die Urteilsfindung ist"}, {"kategorie": "", "text": "Das Recht auf rechtliches Gehör ist in Österreich in mehreren Gesetzen verankert, darunter im Allgemeinen Verwaltungsverfahrensgesetz (AVG) und in der [[Zivilprozessordnung]] (ZPO)"}, {"kategorie": "", "text": "Ein Verstoß gegen dieses Recht kann zur Aufhebung einer gerichtlichen oder behördlichen Entscheidung führen, da es als unverzichtbarer Bestandteil eines fairen Verfahrens gilt."}]'::jsonb, ''),
  ('recht-auf-aunhoerung', 'Recht auf Aunhörung', '', '', '', '', 'Recht auf Anhörung', '[{"kategorie": "jur.", "text": "\"wesentlicher Bestandteil des [[Rechts]] auf ein faires Verfahren, welches gewährleistet, dass eine betroffene Person die Gelegenheit erhält, ihre Position, Argumente und Beweise vor einer gerichtlichen oder behördlichen Entscheidung mündlich oder schriftlich vorzutragen\""}, {"kategorie": "", "text": "Das Recht auf Anhörung stellt sicher, dass die betroffene Person aktiv am Verfahren teilnehmen kann und dass ihre Sichtweise in die Entscheidungsfindung einfließt"}, {"kategorie": "", "text": "Wichtige Merkmale des Rechts auf Anhörung sind:  (i) Möglichkeit zur Stellungnahme: Die betroffene Person darf zu den Sachverhalten, die Grundlage der Entscheidung sein sollen, ihre Argumente und Beweise vorbringen, bevor eine Entscheidung getroffen wird;  (ii) Persönliches Vorbringen: In vielen Fällen hat die betroffene Person das Recht, persönlich gehört zu werden, insbesondere in gerichtlichen oder verwaltungsrechtlichen Verfahren. Dies kann in Form einer mündlichen Anhörung oder einer schriftlichen Stellungnahme erfolgen;  (iii) Wahrung des Anspruchs auf [[rechtliches]] Gehör: Die Anhörung gibt der betroffenen Person die Möglichkeit, auf die Argumente der Gegenseite zu reagieren und sich gegen Vorwürfe oder Sachverhalte zur Wehr zu setzen;  (iv) Transparenz und Fairness: Durch das Recht auf Anhörung wird das Verfahren transparenter und gerechter, da es sicherstellt, dass die betroffene Person vor der Entscheidung involviert ist"}, {"kategorie": "", "text": "Das Recht auf Anhörung ist im österreichischen Recht in verschiedenen Verfahrensgesetzen verankert, wie etwa in der [[Zivilprozessordnung]] (ZPO), dem Allgemeinen Verwaltungsverfahrensgesetz (AVG) und der [[Europäischen]] Menschenrechtskonvention (EMRK)"}, {"kategorie": "", "text": "Ein Verstoß gegen dieses Recht kann dazu führen, dass eine Entscheidung angefochten oder aufgehoben wird, da es ein zentraler Aspekt der Verfahrensgerechtigkeit ist."}]'::jsonb, ''),
  ('faires-vafoan', 'Faires Vafoan', '', '', '', '', 'Faires Verfahren', '[{"kategorie": "jur.", "text": "\"rechtliches Prinzip, das sicherstellt, dass alle Beteiligten eines Gerichts- oder Verwaltungsverfahrens gerecht, gleichberechtigt und transparent behandelt werden\""}, {"kategorie": "", "text": "Dies bedeutet, dass die Rechte jeder Partei im Verfahren respektiert und gewahrt werden, und dass das Verfahren unter Einhaltung bestimmter Mindeststandards durchgeführt wird, um eine gerechte Entscheidung sicherzustellen"}, {"kategorie": "", "text": "Das Konzept ist in vielen nationalen Rechtsordnungen sowie in internationalen Abkommen, wie der [[Europäischen]] Menschenrechtskonvention (EMRK), verankert"}, {"kategorie": "", "text": "Ein faires Verfahren umfasst folgende wesentliche Elemente:  (i) Unabhängiges und unparteiisches Gericht: Die Entscheidung muss von einem [[Gericht]] getroffen werden, das sowohl unabhängig von äußeren Einflüssen als auch unparteiisch gegenüber den Verfahrensbeteiligten ist;  (ii) [[Rechtliches]] Gehör: Jede Partei muss die Möglichkeit haben, ihre Ansichten und Beweise vorzubringen, und der [[Richter]] muss diese berücksichtigen;  (iii) [[Recht]] auf Verteidigung: Insbesondere in [[Strafverfahren]] hat der Angeklagte das Recht, sich zu verteidigen, einen [[Rechtsanwalt]] zu haben und sich gegen die Vorwürfe zur Wehr zu setzen;  (iv) [[Unschuldsvermutung]]: In [[Strafverfahren]] gilt der Grundsatz, dass der Angeklagte bis zum Beweis seiner [[Schuld]] als unschuldig angesehen wird;  (v) Transparenz und Öffentlichkeit: Gerichtsverfahren sollten grundsätzlich öffentlich sein, damit die [[Justiz]] transparent agiert. Ausnahmen sind nur in besonderen Fällen zulässig, etwa zum Schutz von Minderjährigen oder der nationalen Sicherheit;  (vi) Angemessene Verfahrensdauer: Das Verfahren muss innerhalb einer angemessenen Frist abgeschlossen werden, um unangemessene Verzögerungen zu vermeiden;  (vii) Gleichbehandlung der Parteien: Jede Partei muss im Verfahren die gleichen Rechte und Pflichten haben, damit keine Partei bevorzugt oder benachteiligt wird;  (viii) Recht auf Übersetzung und Dolmetschung: Parteien, die die Verhandlungssprache nicht verstehen oder sprechen, haben das Recht auf die Unterstützung durch einen Übersetzer oder Dolmetscher"}, {"kategorie": "", "text": "Diese Prinzipien gewährleisten, dass das Verfahren fair abläuft und dass die Justiz transparent, neutral und gerecht entscheidet. Ein Verstoß gegen das Recht auf ein faires Verfahren kann zur Aufhebung oder Korrektur eines Urteils führen."}]'::jsonb, ''),
  ('recht-auf-a-faires-vafoan', 'Recht auf a faires Vafoan', '', '', '', '', 'Recht auf ein faires Verfahren', '[{"kategorie": "jur.", "text": "\"grundlegendes Prinzip des [[Rechtsstaats]] und dient dem Schutz der Rechte und Freiheiten von Individuen im Rahmen von [[Gerichts-]] und [[Verwaltungsverfahren]]\""}, {"kategorie": "", "text": "Es garantiert, dass alle Verfahrensbeteiligten – insbesondere [[Angeklagte]] in [[Strafverfahren]] – eine faire und gerechte Behandlung vor unabhängigen und unparteiischen Gerichten erhalten"}, {"kategorie": "", "text": "In Österreich und anderen Staaten Europas ist dieses Recht im Artikel 6 der [[Europäischen]] Menschenrechtskonvention (EMRK) verankert. Zu den wichtigsten Aspekten des Rechts auf ein faires Verfahren zählen:  (i) Unabhängiges und unparteiisches Gericht: Das Verfahren muss von einem unabhängigen und neutralen [[Gericht]] geführt werden, das unvoreingenommen über den Fall entscheidet;  (ii) [[Rechtliches]] Gehör: Jede Partei hat das Recht, ihre Argumente vor dem Gericht vorzutragen und [[Beweismittel]] einzubringen. Sie muss die Möglichkeit haben, ihre Sicht der Dinge darzulegen;  (iii) [[Recht]] auf Verteidigung: Insbesondere in [[Strafverfahren]] hat der Angeklagte das Recht, sich zu verteidigen, einen Rechtsbeistand zu wählen oder einen [[Pflichtverteidiger]] zu bekommen, wenn er sich keinen Anwalt leisten kann;  (iv) [[Unschuldsvermutung]]: Jede Person gilt bis zum Beweis ihrer [[Schuld]] als unschuldig. Diese Vermutung darf nicht umgangen werden, und die [[Beweislast]] liegt bei der [[Staatsanwaltschaft]];  (v) Öffentlichkeit des Verfahrens: [[Gerichtsverfahren]] sollen grundsätzlich öffentlich sein, damit Transparenz gewährleistet ist. In bestimmten Fällen kann die Öffentlichkeit jedoch zum Schutz von Privatinteressen oder der öffentlichen Ordnung ausgeschlossen werden;  (vi) Angemessene Verfahrensdauer: Das Verfahren muss innerhalb einer angemessenen Frist durchgeführt werden, um unzumutbare Verzögerungen zu vermeiden;  (vii) Recht auf Übersetzung und Dolmetschung: Parteien, die die Verhandlungssprache nicht verstehen oder sprechen, haben das Recht auf die Unterstützung durch einen Übersetzer oder Dolmetscher"}, {"kategorie": "", "text": "Dieses Recht auf ein faires Verfahren ist von zentraler Bedeutung, um sicherzustellen, dass alle Beteiligten in einem Verfahren gerecht und gleich behandelt werden, unabhängig von ihrer sozialen, ökonomischen oder rechtlichen Stellung. Ein Verstoß gegen dieses Recht kann dazu führen, dass ein Urteil angefochten oder aufgehoben wird."}]'::jsonb, ''),
  ('rechtfeatigenda-notschdaund', 'Rechtfeatigenda Notschdaund', '', '', '', '', 'Rechtfertigender Notstand', '[{"kategorie": "jur.", "text": "\"rechtlicher Grund, der eine ansonsten [[strafbare]] Handlung rechtfertigt, weil sie zur Abwehr einer gegenwärtigen Gefahr notwendig war\""}, {"kategorie": "", "text": "Dabei wird das geschützte Interesse, wie z. B. das Leben oder die Gesundheit, als höherwertig eingestuft als das beeinträchtigte Interesse, wie etwa das Eigentum oder die körperliche Unversehrtheit einer anderen Person"}, {"kategorie": "", "text": "In Österreich ist der rechtfertigende Notstand in § 3 des [[Strafgesetzbuches]] (StGB) geregelt. Er besagt, dass eine Handlung, die eigentlich strafbar wäre, gerechtfertigt sein kann, wenn sie notwendig ist, um eine unmittelbar drohende Gefahr von sich selbst oder anderen abzuwenden"}, {"kategorie": "", "text": "Die Handlung muss also verhältnismäßig sein, was bedeutet, dass kein anderes milderes Mittel zur Gefahrenabwehr zur Verfügung stand. Außerdem darf die Gefahr nicht anders abwendbar gewesen sein"}, {"kategorie": "", "text": "Der rechtfertigende Notstand erlaubt es somit, in Ausnahmesituationen gegen das [[Gesetz]] zu handeln, um größere Schäden zu verhindern, und entlastet den [[Täter]] von einer [[strafrechtlichen]] Verfolgung, sofern die genannten Voraussetzungen erfüllt sind."}]'::jsonb, ''),
  ('schdrofvaschaeafende-umschdaend', 'Schdrofvaschäafende Umschdänd', '', '', '', '', 'Strafverschärfende Umstände', '[{"kategorie": "jur.", "text": "\"Faktoren, die bei der Strafzumessung berücksichtigt werden und dazu führen, dass die Strafe für den Täter erhöht wird\""}, {"kategorie": "", "text": "Strafverschärfende Umstände sind das Gegenstück zu den [[Milderungsgründen]] und zielen darauf ab, die Schwere der Tat und das Verhalten des Täters in den Vordergrund zu stellen"}, {"kategorie": "", "text": "Strafverschärfende Umstände sind im [[österreichischen]] Strafgesetzbuch (StGB) geregelt. Bei der [[Strafzumessung]] ist das Gericht verpflichtet, sowohl [[erschwerende]] als auch [[mildernde]] Umstände zu berücksichtigen, um eine angemessene Strafe zu verhängen"}, {"kategorie": "", "text": "Beispiele für strafverschärfende Umstände: (i) Wiederholungsgefahr: Wenn der Täter bereits wegen ähnlicher Straftaten verurteilt wurde oder als Rückfalltäter gilt, wirkt dies erschwerend;  (ii) Planung und [[Vorsatz]]: Eine Tat, die geplant oder mit besonderem Vorsatz durchgeführt wurde, wird als schwerwiegender angesehen als eine spontane Tat;  (iii) Tatbegehung mit besonderer Brutalität oder Grausamkeit: Eine besonders brutale oder grausame Ausführung der Tat verschärft die Strafe;  (iv) Beteiligung an einer [[kriminellen]] Vereinigung: Wenn der Täter als Teil einer kriminellen Organisation handelt oder gemeinsam mit mehreren Tätern, gilt dies als erschwerend;  (v) Ausnutzung einer Vertrauensstellung: Wenn der Täter eine Vertrauensstellung (z. B. als Betreuer, Lehrer, oder in einem Abhängigkeitsverhältnis) ausnutzt, wird dies als Erschwerungsgrund gewertet;  (vi) Schwere Folgen der Tat: Wenn die Straftat besonders schwere Folgen für das Opfer hat (z. B. schwere körperliche oder seelische Schäden), kann dies die Strafe erhöhen;  (vii) Besondere Rücksichtslosigkeit: Wenn der Täter bei der Tat eine besondere Rücksichtslosigkeit oder Gefährdung anderer Menschen gezeigt hat"}, {"kategorie": "", "text": "Strafverschärfende Umstände führen in der Regel dazu, dass die Strafe im Rahmen des gesetzlich vorgesehenen Strafrahmens erhöht wird. Bei besonders schwerwiegenden Erschwerungsgründen kann die Strafe an der Obergrenze des vorgesehenen Strafmaßes liegen."}]'::jsonb, ''),
  ('easchwerende-umschdaend', 'Easchwerende Umschdänd', '', '', '', '', 'Erschwerende Umstände', '[{"kategorie": "jur.", "text": "\"Faktoren, die bei der Strafzumessung berücksichtigt werden und dazu führen, dass die Strafe für den Täter erhöht wird\""}, {"kategorie": "", "text": "Erschwerende Umstände sind das Gegenstück zu den [[Milderungsgründen]] und zielen darauf ab, die Schwere der Tat und das Verhalten des Täters in den Vordergrund zu stellen"}, {"kategorie": "", "text": "Erschwerende Umstände sind im [[österreichischen]] Strafgesetzbuch (StGB) geregelt. Bei der [[Strafzumessung]] ist das Gericht verpflichtet, sowohl [[erschwerende]] als auch [[mildernde]] Umstände zu berücksichtigen, um eine angemessene Strafe zu verhängen"}, {"kategorie": "", "text": "Beispiele für erschwerdende Umstände: (i) Wiederholungsgefahr: Wenn der Täter bereits wegen ähnlicher Straftaten verurteilt wurde oder als Rückfalltäter gilt, wirkt dies erschwerend;  (ii) Planung und [[Vorsatz]]: Eine Tat, die geplant oder mit besonderem Vorsatz durchgeführt wurde, wird als schwerwiegender angesehen als eine spontane Tat;  (iii) Tatbegehung mit besonderer Brutalität oder Grausamkeit: Eine besonders brutale oder grausame Ausführung der Tat verschärft die Strafe;  (iv) Beteiligung an einer [[kriminellen]] Vereinigung: Wenn der Täter als Teil einer kriminellen Organisation handelt oder gemeinsam mit mehreren Tätern, gilt dies als erschwerend;  (v) Ausnutzung einer Vertrauensstellung: Wenn der Täter eine Vertrauensstellung (z. B. als Betreuer, Lehrer, oder in einem Abhängigkeitsverhältnis) ausnutzt, wird dies als Erschwerungsgrund gewertet;  (vi) Schwere Folgen der Tat: Wenn die Straftat besonders schwere Folgen für das Opfer hat (z. B. schwere körperliche oder seelische Schäden), kann dies die Strafe erhöhen;  (vii) Besondere Rücksichtslosigkeit: Wenn der Täter bei der Tat eine besondere Rücksichtslosigkeit oder Gefährdung anderer Menschen gezeigt hat"}, {"kategorie": "", "text": "Erschwerungsgründe führen in der Regel dazu, dass die Strafe im Rahmen des gesetzlich vorgesehenen Strafrahmens erhöht wird. Bei besonders schwerwiegenden Erschwerungsgründen kann die Strafe an der Obergrenze des vorgesehenen Strafmaßes liegen."}]'::jsonb, ''),
  ('schdrofmuedande-umstaend', 'Schdrofmüdande Umständ', '', '', '', '', 'Strafmildernde Umstände', '[{"kategorie": "jur.", "text": "\"Faktoren, die bei der [[Strafzumessung]] berücksichtigt werden, um die Strafe für den [[Angeklagten]] zu mildern\""}, {"kategorie": "", "text": "Sie zielen darauf ab, den individuellen Umständen des [[Täters]] und der Tat Rechnung zu tragen und können dazu führen, dass das Gericht eine geringere Strafe verhängt, als sie für die begangene [[Straftat]] im [[Gesetz]] vorgesehen ist"}, {"kategorie": "", "text": "Strafmildernde Umstände sind im [[österreichischen]] Strafgesetzbuch (StGB) verankert. Das Gericht ist verpflichtet, bei der Strafbemessung sowohl [[erschwerende]] als auch [[mildernde]] Umstände zu berücksichtigen, um eine gerechte Strafe zu verhängen"}, {"kategorie": "", "text": "Beispiele für strafmildernde Umstände: (i) Reue: Der Täter zeigt nach der Tat aufrichtige Reue und bemüht sich, den verursachten Schaden wiedergutzumachen;  (ii) Geständnis: Ein frühzeitiges und umfassendes Geständnis kann als Milderungsgrund gelten, da es dem Verfahren Zeit und Kosten spart und dem Täter Verantwortungsbewusstsein zuschreibt;  (iii) Täter ist Ersttäter: Wenn der Täter bisher nicht straffällig geworden ist, kann dies als Milderungsgrund angesehen werden;  (iv) Geringes Verschulden: Liegt nur eine geringe Schuld vor, z. B. bei geringerem [[Vorsatz]] oder [[Fahrlässigkeit]], kann dies strafmildernd wirken;  (v) Notlage: Handelte der Täter aus einer wirtschaftlichen oder sozialen Notlage heraus, kann dies als Milderungsgrund gelten;  (vi) Lange Verfahrensdauer: Wenn ein Strafverfahren übermäßig lange dauert, kann dies als Milderungsgrund bei der Strafzumessung berücksichtigt werden;  (vii) Provokation durch das Opfer: Eine Handlung unter starker emotionaler Belastung oder Provokation durch das Opfer kann die Strafe mildern"}, {"kategorie": "", "text": "Strafmildernde Umstände führen in der Regel dazu, dass das Gericht eine niedrigere Strafe innerhalb des gesetzlich vorgesehenen Strafrahmens verhängt. Bei besonders vielen oder starken Milderungsgründen kann das Gericht auch eine [[bedingte]] Strafe oder [[Bewährung]] aussprechen."}]'::jsonb, ''),
  ('muedande-umschdaend', 'Müdande Umschdänd', '', '', '', '', 'Mildernde Umstände', '[{"kategorie": "jur.", "text": "\"Faktoren, die bei der [[Strafzumessung]] berücksichtigt werden, um die Strafe für den [[Angeklagten]] zu mildern\""}, {"kategorie": "", "text": "Sie zielen darauf ab, den individuellen Umständen des [[Täters]] und der Tat Rechnung zu tragen und können dazu führen, dass das Gericht eine geringere Strafe verhängt, als sie für die begangene [[Straftat]] im [[Gesetz]] vorgesehen ist"}, {"kategorie": "", "text": "Mildernde Umstände sind im [[österreichischen]] Strafgesetzbuch (StGB) verankert. Das Gericht ist verpflichtet, bei der Strafbemessung sowohl [[erschwerende]] als auch [[mildernde]] Umstände zu berücksichtigen, um eine gerechte Strafe zu verhängen"}, {"kategorie": "", "text": "Beispiele für mildernde Umstände: (i) Reue: Der Täter zeigt nach der Tat aufrichtige Reue und bemüht sich, den verursachten Schaden wiedergutzumachen;  (ii) Geständnis: Ein frühzeitiges und umfassendes Geständnis kann als Milderungsgrund gelten, da es dem Verfahren Zeit und Kosten spart und dem Täter Verantwortungsbewusstsein zuschreibt;  (iii) Täter ist Ersttäter: Wenn der Täter bisher nicht straffällig geworden ist, kann dies als Milderungsgrund angesehen werden;  (iv) Geringes Verschulden: Liegt nur eine geringe Schuld vor, z. B. bei geringerem [[Vorsatz]] oder [[Fahrlässigkeit]], kann dies strafmildernd wirken;  (v) Notlage: Handelte der Täter aus einer wirtschaftlichen oder sozialen Notlage heraus, kann dies als Milderungsgrund gelten;  (vi) Lange Verfahrensdauer: Wenn ein Strafverfahren übermäßig lange dauert, kann dies als Milderungsgrund bei der Strafzumessung berücksichtigt werden;  (vii) Provokation durch das Opfer: Eine Handlung unter starker emotionaler Belastung oder Provokation durch das Opfer kann die Strafe mildern"}, {"kategorie": "", "text": "Mildernde Umstände führen in der Regel dazu, dass das Gericht eine niedrigere Strafe innerhalb des gesetzlich vorgesehenen Strafrahmens verhängt. Bei besonders vielen oder starken Milderungsgründen kann das Gericht auch eine [[bedingte]] Strafe oder [[Bewährung]] aussprechen."}]'::jsonb, ''),
  ('bedingte-schdrof', 'Bedingte Schdrof', '', '', '', '', 'Bedingte Strafe', '[{"kategorie": "jur.", "text": "\"Freiheits- oder Geldstrafe, die vom Gericht bedingt verhängt wird, das heißt, sie wird nicht sofort vollzogen\""}, {"kategorie": "", "text": "Bei einer Bewährungsstrafe wird die Verhängung oder der Vollzug einer Geld- oder Freiheitsstrafe ausgesetzt, unter der Bedingung, dass der Verurteilte sich innerhalb einer bestimmten Bewährungszeit (auch Probezeit genannt) straffrei verhält"}, {"kategorie": "", "text": "Die Dauer der [[Bewährungszeit]] (Probezeit) wird vom Gericht festgelegt und beträgt in der Regel zwischen ein und fünf Jahren. Während dieser Zeit wird das Verhalten des Verurteilten überwacht"}, {"kategorie": "", "text": "Das Gericht kann dem Verurteilten Auflagen und Weisungen erteilen, die er während der Bewährungszeit zu erfüllen hat, z. B. die Teilnahme an einer Therapie, soziale Dienste oder Meldepflichten. Die Einhaltung dieser Bedingungen ist Voraussetzung für den Erfolg der Bewährung"}, {"kategorie": "", "text": "Das Ziel der Bewährungsstrafe ist es, dem Verurteilten eine zweite Chance zu geben und ihn zu einer straffreien Lebensführung zu motivieren, ohne ihn ins Gefängnis zu schicken. Sie soll zur Resozialisierung beitragen und eine positive Integration in die Gesellschaft fördern"}, {"kategorie": "", "text": "Verstößt der Verurteilte gegen die Bedingungen der Bewährungsstrafe oder begeht er während der Bewährungszeit eine neue Straftat, kann das Gericht die Bewährung widerrufen und die ursprünglich verhängte Geld- oder Freiheitsstrafe vollstrecken lassen"}, {"kategorie": "", "text": "Nach erfolgreichem Abschluss der Bewährungszeit und Erfüllung aller Auflagen gilt die Strafe als verbüßt, und der Verurteilte muss die Geld- bzw. Freiheitsstrafe nicht bezahlen bzw. verbüßen."}]'::jsonb, ''),
  ('schdrof-auf-bewaeaerung', 'Schdrof auf Bewäärung', '', '', '', '', 'Strafe auf Bewährung', '[{"kategorie": "jur.", "text": "\" Freiheitsstrafe, die vom Gericht bedingt verhängt wird, das heißt, sie wird nicht sofort vollzogen\""}, {"kategorie": "", "text": "Bei einer Bewährungsstrafe wird die Verhängung oder der Vollzug einer Freiheitsstrafe ausgesetzt, unter der Bedingung, dass der Verurteilte sich innerhalb einer bestimmten Bewährungszeit (auch Probezeit genannt) straffrei verhält"}, {"kategorie": "", "text": "Die Dauer der [[Bewährungszeit]] (Probezeit) wird vom Gericht festgelegt und beträgt in der Regel zwischen ein und fünf Jahren. Während dieser Zeit wird das Verhalten des Verurteilten überwacht"}, {"kategorie": "", "text": "Das Gericht kann dem Verurteilten Auflagen und Weisungen erteilen, die er während der Bewährungszeit zu erfüllen hat, z. B. die Teilnahme an einer Therapie, soziale Dienste oder Meldepflichten. Die Einhaltung dieser Bedingungen ist Voraussetzung für den Erfolg der Bewährung"}, {"kategorie": "", "text": "Das Ziel der Bewährungsstrafe ist es, dem Verurteilten eine zweite Chance zu geben und ihn zu einer straffreien Lebensführung zu motivieren, ohne ihn ins Gefängnis zu schicken. Sie soll zur Resozialisierung beitragen und eine positive Integration in die Gesellschaft fördern"}, {"kategorie": "", "text": "Verstößt der Verurteilte gegen die Bedingungen der Bewährungsstrafe oder begeht er während der Bewährungszeit eine neue Straftat, kann das Gericht die Bewährung widerrufen und die ursprünglich verhängte Freiheitsstrafe vollstrecken lassen"}, {"kategorie": "", "text": "Nach erfolgreichem Abschluss der Bewährungszeit und Erfüllung aller Auflagen gilt die Strafe als verbüßt, und der Verurteilte muss die Freiheitsstrafe nicht antreten."}]'::jsonb, ''),
  ('freilossung-gegn-geloebnis', 'Freilossung gegn Gelöbnis', '', '', '', '', 'Freilassung gegen Gelöbnis', '[{"kategorie": "jur.", "text": "\"Maßnahme im österreichischen [[Strafprozessrecht]], bei der ein [[Beschuldigter]] oder [[Angeklagter]] vorläufig aus der [[Untersuchungshaft]] entlassen wird, nachdem er ein [[Gelöbnis]] abgegeben hat, bestimmte Auflagen und Bedingungen einzuhalten\""}, {"kategorie": "", "text": "Diese Maßnahme dient als Alternative zur [[Untersuchungshaft]], wenn der Zweck der Haft auch durch die Einhaltung von weniger einschneidenden Maßnahmen ([[gelindere]] Mittel) erreicht werden kann"}, {"kategorie": "", "text": "Die Freilassung gegen Gelöbnis soll gewährleisten, dass der Beschuldigte trotz der Freilassung verfügbar bleibt, um am Verfahren mitzuwirken und der Justiz zur Verfügung zu stehen. Sie soll sicherstellen, dass der Verdächtige nicht flieht, Beweise vernichtet oder den Verfahrensverlauf beeinflusst"}, {"kategorie": "", "text": "Der Beschuldigte muss ein förmliches Versprechen ([[Gelöbnis]]) abgeben, bestimmte Auflagen oder Verhaltensregeln einzuhalten. Diese können individuell festgelegt werden und sind abhängig von der Gefahr, die durch die Haft abgewendet werden soll, z.B. (i) Meldeauflagen (der Beschuldigte muss sich regelmäßig bei einer bestimmten Behörde oder Polizeistelle melden), (ii) Ausreiseverbot (der Beschuldigte darf das Land nicht verlassen), (iii) Kontaktverbot (der Beschuldigte darf keinen Kontakt zu bestimmten Personen aufnehmen, um etwa Zeugenbeeinflussung zu verhindern), (iv) Wohnsitznahme (der Beschuldigte muss an einem bestimmten Ort seinen Wohnsitz haben, der den Behörden bekannt ist), (v) Kautionszahlung: In manchen Fällen kann eine [[Kaution]] als Teil des Gelöbnisses festgesetzt werden, um die Einhaltung der Auflagen sicherzustellen"}, {"kategorie": "", "text": "Die Freilassung gegen Gelöbnis ist in der österreichischen [[Strafprozessordnung]] (StPO) verankert, insbesondere als [[gelinderes]] Mittel im Rahmen der Untersuchungshaft (§§ 173 ff. StPO). Sie darf nur dann angeordnet werden, wenn das Gericht zu der Auffassung kommt, dass durch diese Maßnahme der Untersuchungshaftzweck ebenso erfüllt wird wie durch die Haft selbst"}, {"kategorie": "", "text": "Wenn der Beschuldigte gegen die Bedingungen des Gelöbnisses verstößt, kann die Freilassung widerrufen und der Beschuldigte wieder in Untersuchungshaft genommen werden. Ein solcher Widerruf erfolgt, wenn es Anzeichen dafür gibt, dass der Beschuldigte sich den Auflagen widersetzt oder das Verfahren behindert."}]'::jsonb, ''),
  ('freilossung-gegen-kaution', 'Freilossung gegen Kaution', '', '', '', '', 'Freilassung gegen Kaution', '[{"kategorie": "jur.", "text": "\"Maßnahme im österreichischen [[Strafprozessrecht]], bei der ein [[Beschuldigter]] oder [[Angeklagter]] vorläufig aus der [[Untersuchungshaft]] entlassen wird, nachdem er oder eine dritte Person eine Geldsumme ([[Kaution]]) hinterlegt hat\""}, {"kategorie": "", "text": "Diese Kaution dient als Sicherheitsleistung, um sicherzustellen, dass der Beschuldigte den weiteren Verfahrensverlauf nicht gefährdet und sich den Behörden zur Verfügung hält, insbesondere um Fluchtgefahr zu verhindern"}, {"kategorie": "", "text": "Die österreichische [[Strafprozessordnung]] (StPO) regelt die Freilassung gegen Kaution als eine Form der Freilassung unter Auflagen, die als [[gelinderes]] Mittel angewandt wird, wenn die Untersuchungshaft nicht zwingend notwendig ist (§§ 180 ff. StPO)"}, {"kategorie": "", "text": "Die Höhe der Kaution wird vom [[Gericht]] festgesetzt und richtet sich nach den persönlichen und wirtschaftlichen Verhältnissen des Beschuldigten sowie nach der Schwere der Straftat. Die Summe muss hoch genug sein, um dem Beschuldigten einen finanziellen Anreiz zu geben, die Auflagen zu befolgen und nicht zu fliehen, aber darf auch nicht unangemessen hoch sein"}, {"kategorie": "", "text": "Die Kaution wird entweder in Form von Bargeld, Wertpapieren oder einer Bankgarantie hinterlegt. Es kann auch eine dritte Person (z. B. ein Angehöriger) die Kaution für den Beschuldigten leisten"}, {"kategorie": "", "text": "Zusätzlich zur Kaution kann das Gericht weitere Auflagen an die Freilassung knüpfen, wie z. B.: (i) Meldepflichten bei der Polizei, (ii) Wohnsitzauflagen, (iii) Kontaktverbote oder (iv) Reisepassabgabe, um eine Flucht zu verhindern"}, {"kategorie": "", "text": "Die Kaution wird nach Abschluss desà Strafverfahrens zurückerstattet, sofern der Beschuldigte alle Auflagen eingehalten hat und zu den Verhandlungen erschienen ist. Auch bei einem Freispruch wird die Kaution vollständig zurückgezahlt"}, {"kategorie": "", "text": "Wenn der Beschuldigte gegen die Auflagen verstößt, z. B. indem er flieht oder zu einer Verhandlung nicht erscheint, kann die Kaution vom Gericht eingezogen werden. In diesem Fall wird sie dem [[Staat]] zugeführt und nicht zurückerstattet."}]'::jsonb, ''),
  ('geschlossana-voizug', 'Geschlossana Voizug', '', '', '', '', 'Geschlossener Vollzug', '[{"kategorie": "jur.", "text": "\"strengste Form des [[Strafvollzugs]] in Österreich, bei der die Bewegungsfreiheit der Häftlinge stark eingeschränkt und unter starken Sicherheitsmaßnahmen überwacht wird\""}, {"kategorie": "", "text": "Diese Art des Vollzugs wird für gefährlichere Straftäter oder für solche angewendet, bei denen eine Fluchtgefahr besteht, um sowohl die [[Gesellschaft]] als auch den Strafvollzug geordnet und sicher zu halten"}, {"kategorie": "", "text": "Im geschlossenen Vollzug sind die Insassen in abgeschlossenen Bereichen der [[Justizanstalt]] untergebracht, die durch Sicherheitsvorkehrungen wie Mauern, Zäune, verschlossene Türen und ständige Überwachung (Kameras, Wachpersonal) gesichert sind. Bewegungen innerhalb der Haftanstalt werden streng kontrolliert, und es gibt nur begrenzte Möglichkeiten für die Insassen, sich außerhalb ihrer Zellen zu bewegen"}, {"kategorie": "", "text": "Die Insassen dürfen ihre Zellen nur zu festgelegten Zeiten verlassen und sind auf bestimmte Bereiche der Anstalt beschränkt. Ausgangsrechte und Freiheiten, wie sie im [[offenen]] Vollzug möglich sind, gibt es im geschlossenen Vollzug nicht oder nur in sehr eingeschränktem Maße"}, {"kategorie": "", "text": "Häftlinge im geschlossenen Vollzug werden rund um die Uhr überwacht. Ihre Kommunikation und Bewegungen sind unter Kontrolle, und Besuche finden in gesicherten Räumen unter strikten Bedingungen statt"}, {"kategorie": "", "text": "Der geschlossene Vollzug richtet sich an Straftäter, die als besonders gefährlich gelten oder bei denen eine erhöhte Fluchtgefahr besteht. Dies betrifft häufig Personen, die wegen schwerer Straftaten wie Mord, schwere Gewaltverbrechen oder wiederholte Delikte verurteilt wurden"}, {"kategorie": "", "text": "Auch Häftlinge, die gegen die Regeln des offenen Vollzugs verstoßen oder während der Haft Sicherheitsrisiken darstellen, können in den geschlossenen Vollzug verlegt werden"}, {"kategorie": "", "text": "Verstöße gegen die Anstaltsregeln im geschlossenen Vollzug können zu Sanktionen führen, z. B. zu Isolationsmaßnahmen oder Einschränkungen bei den begrenzten Freiheiten der Insassen."}]'::jsonb, ''),
  ('offana-voizug', 'Offana Voizug', '', '', '', '', 'Offener Vollzug', '[{"kategorie": "jur.", "text": "\"Form des Strafvollzugs, bei der geringere Sicherheitsmaßnahmen angewendet werden, und die Insassen mehr Freiheiten und Eigenverantwortung haben als im [[geschlossenen]] Vollzug\""}, {"kategorie": "", "text": "Der offene Vollzug wird vor allem für straffällige Personen angewendet, die als wenig gefährlich gelten und bei denen die Resozialisierung und Wiedereingliederung in die Gesellschaft im Vordergrund steht"}, {"kategorie": "", "text": "Die Häftlinge im offenen Vollzug haben oft die Möglichkeit, außerhalb der Anstalt zu arbeiten, an Bildungsmaßnahmen teilzunehmen oder sogar Ausgänge zu bekommen, um ihre soziale Integration zu fördern. Dies geschieht jedoch unter bestimmten Auflagen und Bedingungen"}, {"kategorie": "", "text": "Der offene Vollzug ist stark auf die Resozialisierung der Insassen ausgerichtet. Die Häftlinge sollen lernen, sich wieder in die Gesellschaft zu integrieren, selbstständig zu arbeiten und Verantwortung für ihr Leben zu übernehmen, um so auf die Zeit nach der Haftstrafe vorbereitet zu werden"}, {"kategorie": "", "text": "Nicht jeder Häftling kommt für den offenen Vollzug infrage. In der Regel wird diese Form des Vollzugs nur für weniger gefährliche Straftäter angewandt, die eine positive Prognose für ihre Wiedereingliederung haben. Das Verhalten des Insassen während der Haft, die Schwere der Straftat und das Risiko von Fluchtgefahr oder Wiederholungsgefahr werden dabei berücksichtigt"}, {"kategorie": "", "text": "Im offenen Vollzug wird den Insassen oft die Möglichkeit gegeben, einer geregelten Arbeit nachzugehen oder an Ausbildungsmaßnahmen teilzunehmen, die sie auf ein Leben nach der Haft vorbereiten sollen. Diese Arbeits- oder Ausbildungsplätze können sich auch außerhalb der Haftanstalt befinden"}, {"kategorie": "", "text": "Bei Verstößen gegen die Regeln des offenen Vollzugs, wie z. B. unerlaubtem Entfernen oder Nichteinhaltung von Auflagen, kann der Insasse in den geschlossenen Vollzug zurückverlegt werden, wo die Überwachung strenger ist"}, {"kategorie": "", "text": "Der offene Vollzug wird oft als Übergangsphase zum Ende der Haftstrafe eingesetzt. Häftlinge, die kurz vor der Entlassung stehen und die Bedingungen erfüllen, können in den offenen Vollzug verlegt werden, um sie auf ihre Rückkehr in die Gesellschaft vorzubereiten."}]'::jsonb, ''),
  ('gelindare-mittl', 'Gelindare Mittl', '', '', '', '', 'Gelindere Mittel', '[{"kategorie": "jur.", "text": "\"Maßnahmen, die anstelle strengerer Eingriffe angewendet werden können, um ein bestimmtes Ziel zu erreichen, insbesondere in Fällen, in denen ein stärkerer Eingriff in die Rechte einer Person als unverhältnismäßig oder unnötig erachtet wird\""}, {"kategorie": "", "text": "\"Gelindere Mittel\" kommen vor allem in Bereichen wie dem [[Strafprozessrecht]], [[Verwaltungsrecht]] und [[Zivilrecht]] zum Einsatz, wenn es darum geht, weniger einschneidende Alternativen zu wählen, um die Rechte des Einzelnen zu wahren und gleichzeitig den öffentlichen Interessen gerecht zu werden"}, {"kategorie": "", "text": "Im Strafprozessrecht werden gelindere Mittel vor allem im Zusammenhang mit Zwangsmaßnahmen (z. B. Untersuchungshaft) angewendet. Hier wird geprüft, ob eine weniger einschneidende Maßnahme als die Haft den gleichen Zweck erfüllt, wie etwa: (i) Meldeauflagen (regelmäßige Meldungen bei der Polizei), (ii) Hausarrest,\n(iii) Kontaktverbote oder (iv) Kautionszahlungen. Diese Maßnahmen sollen gewährleisten, dass der Beschuldigte den Strafprozess nicht behindert oder flieht, ohne dass er in Haft genommen werden muss"}, {"kategorie": "", "text": "Im [[Verwaltungsrecht]] wird der Begriff verwendet, wenn Behörden bei der Durchsetzung von Gesetzen darauf achten müssen, dass sie mildere Maßnahmen wählen, bevor sie zu schwerwiegenderen Eingriffen wie Zwangsvollstreckungen oder Sanktionen greifen. Ein Beispiel wäre, zunächst Aufforderungen oder Verwarnungen auszusprechen, bevor eine behördliche Maßnahme durchgesetzt wird"}, {"kategorie": "", "text": "Auch im Zivilrecht kann der Grundsatz der gelinderen Mittel zur Anwendung kommen, etwa wenn es um den Schutz von Rechten geht. So könnten im Rahmen einer [[einstweiligen]] Verfügung statt eines vollständigen Verbots bestimmte Auflagen verhängt werden, die weniger drastisch in die Rechte des Betroffenen eingreifen, aber dennoch den beabsichtigten Schutz bieten."}]'::jsonb, ''),
  ('rechtliches-ghoea', 'Rechtliches Ghöa', '', '', '', '', 'Rechtliches Gehör', '[{"kategorie": "jur.", "text": "\"grundlegendes Verfahrensrecht in Österreich, das jeder Person, die von einem gerichtlichen oder behördlichen Verfahren betroffen ist, das Recht gibt, sich zu den gegen sie erhobenen Vorwürfen oder Maßnahmen zu äußern\""}, {"kategorie": "", "text": "Es ist ein zentrales Prinzip des rechtsstaatlichen Verfahrens und garantiert, dass Betroffene die Möglichkeit haben, ihre Sichtweise darzulegen, Beweise vorzubringen und sich zu Verfahrensakten zu äußern, bevor eine Entscheidung getroffen wird"}, {"kategorie": "", "text": "Das rechtliche Gehör ist in Österreich ein verfassungsmäßig geschütztes Recht und ein wesentlicher Bestandteil eines fairen Verfahrens. Es dient dazu, die \"Waffengleichheit\" zwischen den Verfahrensparteien sicherzustellen. Es gewährleistet, dass die betroffene Person in einem Verfahren die Möglichkeit hat, sich aktiv an der Klärung des Sachverhalts zu beteiligen, ihre Argumente vorzubringen und auf die Ergebnisse der Ermittlung Einfluss zu nehmen"}, {"kategorie": "", "text": "Das rechtliche Gehör beinhaltet das Recht auf Information, d. h. die betroffene Person muss über den Stand des Verfahrens, die Vorwürfe und alle für das Verfahren wesentlichen Umstände informiert werden. Zudem hat die Person das Recht, in die Akten Einsicht zu nehmen, sich mit den Beweisen auseinanderzusetzen und Stellungnahmen einzureichen, bevor eine endgültige Entscheidung ergeht"}, {"kategorie": "", "text": "In vielen Fällen umfasst das rechtliche Gehör auch das Recht auf eine mündliche Verhandlung, in der die betroffene Person ihre Argumente vorbringen und sich zur Sache äußern kann. Insbesondere im [[Strafrecht]] und [[Verwaltungsverfahren]] ist die Möglichkeit zur Verteidigung und Stellungnahme ein wesentlicher Bestandteil des Verfahrens"}, {"kategorie": "", "text": "Das rechtliche Gehör ist ein wesentliches Prinzip des [[Rechtsstaats]] und dient der Sicherung der Gerechtigkeit. Es verhindert, dass Entscheidungen über eine Person getroffen werden, ohne dass diese die Möglichkeit hatte, sich zu den Vorwürfen zu äußern und ihre Rechte wahrzunehmen"}, {"kategorie": "", "text": "Eine Verletzung des rechtlichen Gehörs kann zur Aufhebung oder Anfechtung einer behördlichen oder gerichtlichen Entscheidung führen. Wenn das rechtliche Gehör verweigert wurde, gilt das Verfahren als fehlerhaft und die betroffene Person kann in der Regel [[Rechtsmittel]] dagegen einlegen."}]'::jsonb, ''),
  ('oabeitsmoakd-soeawis', 'Oabeitsmoakd-Söawis', '', '', '', '', 'Arbeitsmarkt-Service', '[{"kategorie": "", "text": "Das AMS unterstützt sowohl Arbeitnehmer als auch Arbeitgeber und spielt eine zentrale Rolle bei der Regulierung des Arbeitsmarktes"}, {"kategorie": "", "text": "Das AMS hilft Arbeitssuchenden, eine neue Beschäftigung zu finden, indem es Stellenangebote sammelt, diese an Jobsuchende vermittelt und Bewerbungsunterstützung bietet. Es arbeitet eng mit Arbeitgebern zusammen, um offene Stellen zu besetzen"}, {"kategorie": "", "text": "Um die Beschäftigungschancen zu erhöhen, bietet das AMS verschiedene Fortbildungsprogramme, Schulungen und Berufsausbildungsmaßnahmen an. Diese Maßnahmen sollen den Arbeitslosen helfen, neue Qualifikationen zu erwerben, die auf dem Arbeitsmarkt gefragt sind"}, {"kategorie": "", "text": "Das AMS ist verantwortlich für die Auszahlung von [[Arbeitslosengeld]], [[Notstandshilfe]] und anderen sozialen Unterstützungsleistungen. Es prüft die Ansprüche und unterstützt die finanzielle Absicherung der Betroffenen während der Arbeitslosigkeit"}, {"kategorie": "", "text": "Auch Arbeitgeber können die Dienste des AMS in Anspruch nehmen. Das AMS bietet Unterstützung bei der Personalsuche, hilft bei der Verwaltung von Förderungen und bietet Einstellungsförderungen an, um die Schaffung von Arbeitsplätzen zu erleichtern."}]'::jsonb, ''),
  ('tatbestaund', 'Tåtbestaund', '', '', '', '', 'Tatbestand', '[{"kategorie": "jur.", "text": "\"zentraler Begriff im [[Strafrech]], welcher die gesetzlich festgelegten Merkmale oder Voraussetzungen beschreibt, die erfüllt sein müssen, damit eine bestimmte [[Straftat]] vorliegt\""}, {"kategorie": "", "text": "Der Tatbestand  bildet die Grundlage dafür, ob ein Verhalten oder eine Handlung als strafbar gilt und somit eine [[Strafe]] nach sich zieht"}, {"kategorie": "", "text": "Ein Tatbestand umfasst die rechtlichen Kriterien, die in einem [[Gesetz]] definiert sind, um eine bestimmte Straftat zu beschreiben. Diese Merkmale müssen alle erfüllt sein, damit die Tat als strafbar eingestuft werden kann"}, {"kategorie": "", "text": "Objektive Merkmale beziehen sich auf die äußeren, feststellbaren Umstände der Tat, wie z. B. der Tatort, die Tatzeit, der Täter und die Tatwaffe. Diese müssen nachweisbar sein"}, {"kategorie": "", "text": "Subjektive Merkmale betreffen den inneren Zustand des Täters, insbesondere dessen [[Vorsatz]] (ob er die Tat absichtlich oder bewusst begangen hat) oder [[Fahrlässigkeit]] (ob er die Sorgfaltspflichten missachtet hat)"}, {"kategorie": "", "text": "Wenn alle Tatbestandsmerkmale in einem konkreten Fall vorliegen, spricht man von der Tatbestandsverwirklichung. Erst dann prüft das Gericht, ob die Handlung rechtswidrig und schuldhaft ist und somit zu einer Strafbarkeit führt"}, {"kategorie": "", "text": "Der Tatbestand allein reicht nicht aus, um eine [[Strafe]] zu verhängen. Nach der Erfüllung des Tatbestands wird weiter geprüft, ob die Tat auch rechtswidrig und schuldhaft begangen wurde. Nur wenn alle Voraussetzungen vorliegen, wird der Täter bestraft."}]'::jsonb, ''),
  ('betriibsrat', 'Betriibsråt', '', '', '', '', 'Betriebsrat', '[{"kategorie": "jur.", "text": "\"gewählte Interessenvertretung der Arbeitnehmer in einem Unternehmen, die dafür sorgt, dass die Rechte und Interessen der Mitarbeiter gegenüber dem Arbeitgeber gewahrt und gefördert werden\""}, {"kategorie": "", "text": "Der Betriebsrat vertritt die Arbeitnehmer in betriebsinternen Angelegenheiten und hat Mitbestimmungsrechte in verschiedenen Bereichen der Unternehmensführung, wie z. B. Arbeitsbedingungen, Arbeitszeiten und Kündigungen"}, {"kategorie": "", "text": "Der Betriebsrat vertritt die kollektiven Interessen der Arbeitnehmer im Betrieb gegenüber dem Arbeitgeber und achtet darauf, dass geltende Arbeitsgesetze, [[Tarifverträge]] und Betriebsvereinbarungen eingehalten werden"}, {"kategorie": "", "text": "Die Mitglieder des Betriebsrats werden von den Arbeitnehmern des Unternehmens gewählt. Betriebe mit mindestens fünf ständigen Arbeitnehmern haben das Recht, einen Betriebsrat zu wählen. Die Wahl findet in regelmäßigen Abständen (meist alle vier Jahre) statt"}, {"kategorie": "", "text": "Der Betriebsrat hat umfangreiche Mitbestimmungsrechte bei Themen, die die Arbeitsbedingungen betreffen, wie: (i) Arbeitszeiten und Überstunden, (ii) Urlaubsregelungen, (iii) Sicherheit am Arbeitsplatz und (iv) Betriebsvereinbarungen"}, {"kategorie": "", "text": "Bei Kündigungen muss der Betriebsrat gehört werden, und er kann Einspruch einlegen, wenn er die Kündigung als ungerechtfertigt ansieht"}, {"kategorie": "", "text": "Mitglieder des Betriebsrats genießen besonderen Kündigungsschutz. Sie dürfen nicht ohne weiteres entlassen oder benachteiligt werden, um sicherzustellen, dass sie ihre Aufgaben frei und unabhängig ausüben können."}]'::jsonb, ''),
  ('bedingte-entlossung', 'Bedingte Entlossung', '', '', '', '', 'Bedingte Entlassung', '[{"kategorie": "jur.", "text": "\"vorzeitige Entlassung eines Verurteilten aus der [[Strafhaft]] unter [[Bewährungsauflagen]]\""}, {"kategorie": "", "text": "Der Verurteilte wird unter Auflagen aus der Haft entlassen, muss sich jedoch während einer festgelegten [[Bewährungszeit]] bewähren"}, {"kategorie": "", "text": "Die bedingte Entlassung soll die Resozialisierung fördern und die Wiedereingliederung des Häftlings in die Gesellschaft ermöglichen"}, {"kategorie": "", "text": "Die bedingte Entlassung kann gewährt werden, wenn der Verurteilte einen Teil der Strafe verbüßt hat (in der Regel mindestens ein bzw. zwei Drittel der Strafe) und das Gericht zu der Auffassung gelangt, dass keine Wiederholungsgefahr besteht und der Verurteilte sich in die [[Gesellschaft]] resozialisieren lässt"}, {"kategorie": "", "text": "Bei einer [[lebenslangen]] Freiheitsstrafe kann die Entlassung frühestens nach 15 Jahren beantragt werden, in besonderen Fällen auch später"}, {"kategorie": "", "text": "Der Verurteilte wird auf [[Bewährung]] entlassen, das heißt, er muss sich während der [[Bewährungszeit]] (häufig mehrere Jahre) an bestimmte Auflagen halten. Diese können Meldepflichten, Therapieauflagen oder ein Verbot bestimmter Aktivitäten oder Kontakte umfassen"}, {"kategorie": "", "text": "Wenn der Verurteilte gegen die Bewährungsauflagen verstößt oder erneut straffällig wird, kann die bedingte Entlassung widerrufen werden. In diesem Fall muss der Verurteilte die restliche Strafe in der Justizanstalt verbüßen"}, {"kategorie": "", "text": "Die Entscheidung über die bedingte Entlassung trifft das zuständige Gericht. Es prüft, ob die Voraussetzungen erfüllt sind und ob der Entlassene eine Gefahr für die Gesellschaft darstellen könnte."}]'::jsonb, ''),
  ('lebnslaunge-freiheitsschdrof', 'Lebnslaunge Freiheitsschdrof', '', '', '', '', 'Lebenslange Freiheitsstrafe', '[{"kategorie": "jur.", "text": "\"schwerste Form der [[Freiheitsstrafe]], bei der eine Person durch ein rechtskräftiges [[Urteil]] unbefristet inhaftiert wird und theoretisch für den Rest ihres Lebens in einer [[Justizanstalt]] verbleiben muss\""}, {"kategorie": "", "text": "Sie wird in der Regel für besonders schwere [[Verbrechen]] wie Mord, Völkermord oder schwere [[Gewaltverbrechen]] verhängt"}, {"kategorie": "", "text": "In Österreich kann ein Verurteilter in der Regel nach 15 Jahren (unter bestimmten Umständen mehr) die [[bedingte]] Entlassung beantragen, wenn er als resozialisiert gilt und keine Gefahr für die [[Gesellschaft]] mehr darstellt"}, {"kategorie": "", "text": "Die vorzeitige Entlassung erfolgt nicht automatisch. Der Verurteilte muss einen Antrag stellen, und das Gericht prüft, ob die Voraussetzungen für eine Entlassung vorliegen. Dazu gehört die Bewertung, ob der Verurteilte rehabilitiert ist und keine Wiederholungsgefahr besteht"}, {"kategorie": "", "text": "Verurteilte, die zu einer lebenslangen Freiheitsstrafe verurteilt wurden, werden häufig in Hochsicherheitsgefängnissen untergebracht, insbesondere wenn das Risiko von Flucht oder weiteren Straftaten besteht"}, {"kategorie": "", "text": "Aufgrund der Schwere der [[Verbrechen]] und der langen Haftdauer stehen Verurteilte unter besonders strengen Auflagen und Sicherheitsvorkehrungen. Gleichzeitig gibt es aber auch Bemühungen zur Resozialisierung, wie etwa Arbeitsprogramme oder Therapiemöglichkeiten."}]'::jsonb, ''),
  ('aunklage', 'Aunklåge', '', '', '', '', 'Anklage', '[{"kategorie": "jur.", "text": "\"förmliche Beschuldigung einer Person durch die [[Staatsanwaltschaft]] in einem [[Strafverfahren]], die besagt, dass diese Person eine Straftat begangen hat\""}, {"kategorie": "", "text": "Mit der Anklage wird der Beschuldigte offiziell vor Gericht gestellt, und das Verfahren tritt in die [[Hauptverhandlung]] ein, in der die Schuldfrage geklärt wird"}, {"kategorie": "", "text": "Die Staatsanwaltschaft erhebt Anklage, wenn sie nach Abschluss der Ermittlungen zu dem Schluss kommt, dass ein hinreichender [[Tatverdacht]] gegen den [[Beschuldigten]] besteht und genügend Beweismittel vorliegen, um das Verfahren vor Gericht zu bringen"}, {"kategorie": "", "text": "Die Anklage enthält die konkreten Vorwürfe gegen den Beschuldigten, die genaue Beschreibung der Tat, die dem Beschuldigten zur Last gelegt wird, sowie die gesetzliche Grundlage, auf der die Anklage beruht (z. B. ein bestimmter Paragraf des [[Strafgesetzbuchs]])"}, {"kategorie": "", "text": "Mit der Anklageerhebung wird die Hauptverhandlung vor einem Gericht eingeleitet. Der [[Richter]] entscheidet dann, ob die Anklage zur Verhandlung zugelassen wird. Wenn dies der Fall ist, wird der Beschuldigte als [[Angeklagter]] bezeichnet und muss sich vor Gericht verantworten"}, {"kategorie": "", "text": "Trotz der Anklage gilt der Beschuldigte bis zur rechtskräftigen Verurteilung als unschuldig. Erst durch das Urteil wird entschieden, ob der Angeklagte schuldig ist oder freigesprochen wird"}, {"kategorie": "", "text": "Falls das Verfahren zu einem Urteil führt, kann dieses durch [[Rechtsmittel]] wie Berufung oder [[Nichtigkeitsbeschwerde]] angefochten werden."}]'::jsonb, ''),
  ('schdrofrechtliche-vafoigung', 'Schdrofrechtliche Vafoigung', '', '', '', '', 'Strafrechtliche Verfolgung', '[{"kategorie": "jur.", "text": "\"Prozess, bei dem der [[Staat]] durch die [[Staatsanwaltschaft]] und die Strafverfolgungsbehörden (wie Polizei und Ermittlungsbehörden) gegen Personen vorgeht, die einer Straftat verdächtigt oder beschuldigt werden\""}, {"kategorie": "", "text": "Ziel der strafrechtlichen Verfolgung ist es, Straftaten aufzuklären, die Verantwortlichen zur Rechenschaft zu ziehen und sie gegebenenfalls vor Gericht zu stellen, um eine Strafe zu verhängen"}, {"kategorie": "", "text": "Die strafrechtliche Verfolgung beginnt mit der Ermittlung einer Straftat, meist durch die Polizei oder andere Ermittlungsbehörden. Dies kann durch eine [[Strafanzeige]], Eigeninitiative der Behörden oder durch Hinweise von Dritten ausgelöst werden"}, {"kategorie": "", "text": "Die Staatsanwaltschaft leitet die strafrechtliche Verfolgung und entscheidet, ob [[Anklage]] erhoben wird. Sie sammelt Beweise, beauftragt die Ermittlungsbehörden und vertritt den Staat in einem späteren Strafverfahren"}, {"kategorie": "", "text": "Im Rahmen der strafrechtlichen Verfolgung werden Beweise gesammelt, Zeugen befragt und Verdächtige vernommen. Es kann zu Zwangsmaßnahmen wie Durchsuchungen, Beschlagnahmungen oder [[Untersuchungshaft]] kommen, wenn dies zur Sicherung des Verfahrens notwendig ist"}, {"kategorie": "", "text": "Nach Abschluss der Ermittlungen entscheidet die Staatsanwaltschaft, ob die Anklage erhoben wird. Wenn genügend Beweise vorliegen, wird der Fall vor ein Strafgericht gebracht. Andernfalls kann das Verfahren eingestellt werden"}, {"kategorie": "", "text": "Die strafrechtliche Verfolgung unterliegt den Grundsätzen des [[Rechtsstaats]]. Dazu gehören die Unschuldsvermutung (bis zur Verurteilung) und das Recht des Beschuldigten auf eine faire Verteidigung"}, {"kategorie": "", "text": "Die strafrechtliche Verfolgung bezieht sich auf den Prozess der Aufklärung und Verfolgung einer Straftat bis zur [[Anklageerhebung]] und einem [[Urteil]], währenddem die [[Strafvollstreckung]] nach einem rechtskräftigen [[Urteil]] den Vollzug der Strafe (z. B. Freiheitsstrafe) beinhaltet."}]'::jsonb, ''),
  ('recht-und-hoftschutzrichta', 'Recht- und Hoftschutzrichta', '', '', '', '', 'Recht- und Haftschutzrichter', '[{"kategorie": "jur.", "text": "\"Richter, der für die Überprüfung und Kontrolle von Zwangsmaßnahmen zuständig ist, die in das Recht auf Freiheit oder andere Grundrechte eingreifen, insbesondere im Rahmen von Ermittlungsverfahren\""}, {"kategorie": "", "text": "Der Rechtsschutzrichter kontrolliert Zwangsmaßnahmen wie Hausdurchsuchungen, Telefonüberwachungen oder die Beschlagnahme von Beweismitteln. Er prüft, ob die Eingriffe in die [[Grundrechte]] der betroffenen Personen rechtlich gerechtfertigt sind"}, {"kategorie": "", "text": "Als Haftschutzrichter ist er zuständig für die Überprüfung der [[Untersuchungshaft]]. Er entscheidet, ob die Anordnung oder Fortsetzung der Untersuchungshaft gerechtfertigt ist, und ob alternative Maßnahmen, wie die Haftentlassung gegen Auflagen, möglich sind"}, {"kategorie": "", "text": "Der Rechtsschutzrichter fungiert als Garantie für den Schutz der [[Grundrechte]] der Beschuldigten, indem er sicherstellt, dass Maßnahmen der [[Strafverfolgung]] und Ermittlung nur unter strenger Beachtung der [[Rechtsstaatlichkeit]] durchgeführt werden"}, {"kategorie": "", "text": "Bei seiner Entscheidung achtet der Rechtsschutzrichter auf die Verhältnismäßigkeit der Zwangsmaßnahmen. Diese dürfen nur ergriffen werden, wenn sie erforderlich sind und es keine milderen Mittel gibt, um den Zweck zu erreichen"}, {"kategorie": "", "text": "Die [[Staatsanwaltschaft]] oder Ermittlungsbehörden müssen in bestimmten Fällen beim Rechtsschutzrichter eine Genehmigung für Maßnahmen beantragen, die tief in die Rechte der betroffenen Personen eingreifen. Der Richter prüft diesen Antrag und erteilt gegebenenfalls die Erlaubnis oder lehnt sie ab."}]'::jsonb, ''),
  ('gerichtlicha-vagleich', 'Gerichtlicha Vagleich', '', '', '', '', 'Gerichtlicher Vergleich', '[{"kategorie": "jur.", "text": "\"einvernehmliche Vereinbarung zwischen den streitenden Parteien, die während eines [[Gerichtsverfahrens]] getroffen wird und vom [[Gericht]] als rechtsverbindliche Entscheidung anerkannt wird\""}, {"kategorie": "", "text": "Durch diesen Vergleich wird der Rechtsstreit außergerichtlich beigelegt, ohne dass es zu einem [[Urteil]] kommt"}, {"kategorie": "", "text": "Der gerichtliche Vergleich basiert auf der freiwilligen Einigung beider Parteien über den Streitgegenstand, oft unter Mitwirkung des Gerichts. Er kann während der Verhandlung oder im Vorfeld eines Urteils zustande kommen"}, {"kategorie": "", "text": "Der Vergleich wird im Protokoll festgehalten und ist rechtlich bindend. Er hat die gleiche Wirkung wie ein Gerichtsurteil und ist sofort vollstreckbar, wenn eine Partei die vereinbarten Bedingungen nicht einhält"}, {"kategorie": "", "text": "Mit dem Abschluss des Vergleichs ist das gerichtliche Verfahren beendet. Es gibt keine Notwendigkeit für eine weitere gerichtliche Entscheidung oder ein Urteil"}, {"kategorie": "", "text": "Der gerichtliche Vergleich ermöglicht eine schnelle und kostengünstige Lösung des Konflikts, vermeidet die Unsicherheiten eines Urteils und ermöglicht den Parteien, sich auf einen Kompromiss zu einigen, der für beide akzeptabel ist."}]'::jsonb, ''),
  ('einstwaeulige-vafuegung', 'Einstwäulige Vafügung', '', '', '', '', 'Einstweilige Verfügung', '[{"kategorie": "jur.", "text": "\"vorläufige gerichtliche Anordnung, die erlassen wird, um in dringenden Fällen Rechte zu sichern oder eine drohende Gefahr abzuwenden, bevor eine endgültige Entscheidung im Hauptverfahren getroffen wird\""}, {"kategorie": "", "text": "Sie ist eine schnelle, vorübergehende Maßnahme, die nur so lange gilt, bis das Hauptverfahren abgeschlossen und eine endgültige Entscheidung getroffen wird"}, {"kategorie": "", "text": "Einstweilige Verfügungen können in vielen Rechtsbereichen erlassen werden, beispielsweise im [[Zivilrecht]], um Unterlassungen, Leistungen oder Sicherungen zu erzwingen"}, {"kategorie": "", "text": "Beispiele: (i) Unterlassungsverfügungen zur Verhinderung von schädigenden Handlungen (z. B. Verhinderung von Bauten),  (ii) Leistungsverfügungen zur vorläufigen Durchsetzung von Ansprüchen (z. B. Zahlung von Geld),  (iii) Sicherungsverfügungen zum Schutz von Vermögenswerten"}, {"kategorie": "", "text": "Eine einstweilige Verfügung wird nur erlassen, wenn eine dringende Notwendigkeit besteht, um irreparablen Schaden zu verhindern oder den Verlust von Rechten zu vermeiden"}, {"kategorie": "", "text": "Der Antragsteller muss glaubhaft machen, dass eine Rechtsverletzung droht oder bereits eingetreten ist und dass ohne sofortige Maßnahme erheblicher Schaden oder Nachteile entstehen würden. Zudem muss der Antragsteller darlegen, dass keine andere Möglichkeit besteht, den Schaden abzuwenden"}, {"kategorie": "", "text": "Einstweilige Verfügungen sind oft sofort vollstreckbar, d.h. dass die angeordnete Maßnahme sofort umgesetzt wird, bis das Gericht im Hauptverfahren eine endgültige Entscheidung trifft"}, {"kategorie": "", "text": "Gegen eine einstweilige Verfügung kann die betroffene Partei Rechtsmittel einlegen, etwa in Form eines [[Widerspruchs]] oder einer [[Beschwerde]]. Das Gericht überprüft dann, ob die Verfügung gerechtfertigt war."}]'::jsonb, ''),
  ('oestarreichischa-zoi', 'Östarreichischa Zoi', '', '', '', '', 'Österreichischer Zoll', '[{"kategorie": "allg.", "text": "\"staatliche Institution, die für die Überwachung des grenzüberschreitenden Warenverkehrs, die Einhaltung von Zollvorschriften und die Erhebung von Zöllen und Steuern verantwortlich ist\""}, {"kategorie": "", "text": "Die Zollbehörde ist Teil des Bundesministeriums für Finanzen und hat sowohl fiskalische Aufgaben als auch solche im Bereich der Sicherheit und Wirtschaftskontrolle"}, {"kategorie": "", "text": "Als Teil der Europäischen Zollunion richtet sich die österreichische Zollbehörde nach den Regelungen und Vorschriften der Europäischen Union. Dies bedeutet, dass sie für die Einhaltung von EU-Zollvorschriften verantwortlich ist, die für den gesamten Binnenmarkt gelten"}, {"kategorie": "", "text": "Die Zollbehörde ist für die Zollabfertigung von Waren an den österreichischen Außengrenzen verantwortlich. Dies betrifft vor allem Flughäfen und Grenzstationen, über die Waren in die EU gelangen"}, {"kategorie": "", "text": "Ein zentraler Bereich der Arbeit der Zollbehörde ist die Bekämpfung von Schmuggel und anderen illegalen Handelsaktivitäten. Dies umfasst den Schmuggel von Waren wie Zigaretten, Drogen, gefälschten Produkten oder geschmuggelten Waffen"}, {"kategorie": "", "text": "Die österreichische Zollbehörde arbeitet eng mit anderen nationalen Behörden wie der [[Polizei]], der [[Staatsanwaltschaft]] und dem [[Bundesheer]] zusammen, um die Sicherheit an den Grenzen zu gewährleisten"}, {"kategorie": "", "text": "Sie kooperiert auch mit internationalen Zollbehörden und Organisationen wie der Weltzollorganisation (WCO), um den internationalen Handel zu regulieren und illegale Aktivitäten grenzüberschreitend zu bekämpfen."}]'::jsonb, ''),
  ('eko-cobra', 'EKO Cobra', '', '', '', '', 'EKO Cobra', '[{"kategorie": "", "text": "Sie ist eine der bekanntesten und schlagkräftigsten Spezialeinheiten des Landes und kommt bei besonders gefährlichen oder komplexen Situationen zum Einsatz, wie etwa bei Geiselnahmen, Terroranschlägen oder der Festnahme von schwer bewaffneten Kriminellen. Die Einheit ist dem Bundesministerium für Inneres (BMI) unterstellt"}, {"kategorie": "", "text": "Das Einsatzkommando Cobra wurde 1978 gegründet (ursprünglich als \"Gendarmerieeinsatzkommando\"), nach dem Anschlag auf die OPEC-Konferenz in Wien 1975, um eine schlagkräftige Einheit für den Kampf gegen Terrorismus zu schaffen"}, {"kategorie": "", "text": "Die Hauptaufgabe der Cobra ist der Antiterrorkampf. Sie wird bei Geiselnahmen, Entführungen, terroristischen Bedrohungen und Amoklagen eingesetzt"}, {"kategorie": "", "text": "Darüber hinaus führt die Cobra auch Personenschutz für besonders gefährdete Persönlichkeiten durch, unterstützt bei der Festnahme von Schwerkriminellen und ist bei Luftsicherheitsoperationen wie der Sicherung von Flugzeugen beteiligt"}, {"kategorie": "", "text": "Sie ist auch für Geiselbefreiungen und die Bekämpfung von organisierter Kriminalität sowie Gefahrenabwehr in Extremsituationen verantwortlich"}, {"kategorie": "", "text": "Die Cobra ist Teil der Bundespolizei und untersteht dem Direktor der Spezialeinheiten, der dem Innenministerium angehört. Die Einheit ist zentral organisiert, aber auch in mehreren Standorten in Österreich verteilt, um rasch an verschiedenen Einsatzorten verfügbar zu sein"}, {"kategorie": "", "text": "Sie hat verschiedene spezialisierte Teams, die auf unterschiedliche Aufgaben spezialisiert sind, wie etwa Sprengstoffentschärfung, Scharfschützen, Taucher oder Abseilspezialisten"}, {"kategorie": "", "text": "Die Cobra verwendet hochmoderne Ausrüstung und Waffensysteme, die speziell für Antiterror- und Spezialoperationen entwickelt wurden. Dazu gehören Scharfschützengewehre, Sturmgewehre, Schutzwesten sowie modernste Kommunikationstechnologie"}, {"kategorie": "", "text": "Die Cobra arbeitet eng mit anderen internationalen Spezialeinheiten zusammen und nimmt an gemeinsamen Übungen und Einsätzen teil. Sie ist Mitglied der ATLAS-Gruppe, einem Zusammenschluss europäischer Spezialeinheiten, die bei grenzüberschreitenden Bedrohungen, wie Terrorismus oder schwerer organisierter Kriminalität, kooperieren."}]'::jsonb, ''),
  ('oestarreichische-polizei', 'Östarreichische Polizei', '', '', '', '', 'Österreichische Polizei', '[{"kategorie": "pol.", "text": "\"staatliche Institution, die für die Aufrechterhaltung der öffentlichen Sicherheit, den Schutz der Bürger und die Durchsetzung von [[Gesetzen]] in Österreich zuständig ist\""}, {"kategorie": "", "text": "Sie gehört zur [[Exekutive]] und untersteht dem Bundesministerium für Inneres (BMI). Die österreichische Polizei ist in verschiedene Einheiten und Abteilungen gegliedert und spielt eine zentrale Rolle bei der Kriminalitätsbekämpfung, Gefahrenabwehr und Sicherheitsgewährleistung"}, {"kategorie": "", "text": "Seit 2005 gibt es eine einheitliche Bundespolizei, die aus der Zusammenlegung von Bundessicherheitswache, Gendarmerie und Kriminalpolizei hervorgegangen ist"}, {"kategorie": "", "text": "Sie gliedert sich in verschiedene Landespolizeidirektionen, die für die einzelnen [[Bundesländer]] zuständig sind. Innerhalb der Länder sind diese Direktionen in Polizeiinspektionen aufgeteilt, die die lokale Ebene der Polizeiarbeit repräsentieren"}, {"kategorie": "", "text": "Die Kriminalpolizei ist eine spezialisierte Einheit der österreichischen Polizei, die sich auf die Untersuchung von Straftaten konzentriert. Sie befasst sich mit der Aufklärung schwerer Verbrechen wie Mord, Diebstahl, Betrug, Drogenhandel und organisierter Kriminalität"}, {"kategorie": "", "text": "Die österreichische Polizei verfügt auch über mehrere Spezialeinheiten, die für besondere Einsätze ausgebildet sind: (i) Cobra (eine Spezialeinheit für Antiterror-Einsätze und Geiselbefreiungen),  (ii) EKO Cobra und WEGA (beide Einheiten sind für den Schutz besonders gefährdeter Personen und die Bewältigung von Extremsituationen, wie etwa terroristischen Bedrohungen oder schwer bewaffneten Kriminellen, zuständig)"}, {"kategorie": "", "text": "Die österreichische Polizei arbeitet eng mit anderen staatlichen Behörden, wie der [[Staatsanwaltschaft]], den [[Gerichten]], dem [[Bundesheer]] und den [[Zollbehörden]], zusammen, ebenso auch mit internationalen Polizeibehörden wie Europol oder Interpol"}, {"kategorie": "", "text": "Die österreichische Polizei handelt auf Grundlage von Gesetzen wie dem Sicherheitspolizeigesetz (SPG), der Strafprozessordnung (StPO) und dem Polizeilichen Staatsschutzgesetz (PStSG). Diese Gesetze regeln die Aufgaben, Befugnisse und Grenzen polizeilichen Handelns"}, {"kategorie": "", "text": "Sie handelt im Rahmen eines strikten rechtlichen Rahmens, der sicherstellt, dass ihre Maßnahmen im Einklang mit der [[Verfassung]] und den [[Menschenrechten]] stehen. Mit ihrer breiten Palette an Aufgaben und spezialisierten Einheiten trägt die Polizei maßgeblich zur [[Rechtsstaatlichkeit]] und zum Schutz der Bevölkerung in Österreich bei."}]'::jsonb, ''),
  ('europaeische-menschnrechtskonvention', 'Europäische Menschnrechtskonvention', '', '', '', '', 'Europäische Menschenrechtskonvention', '[{"kategorie": "", "text": "Österreich trat der EMRK 1958 bei, und sie hat in Österreich Verfassungsrang, was bedeutet, dass sie denselben rechtlichen Status wie die österreichische [[Bundesverfassung]] hat. Sie ist integraler Bestandteil der österreichischen [[Rechtsordnung]] und hat Vorrang vor einfachen [[Gesetze]]"}, {"kategorie": "", "text": "Die EMRK enthält eine Reihe von [[Grundrechten]] und Freiheiten, die jeder Person in den Mitgliedstaaten zustehen. Zu den wichtigsten Rechten gehören:  (i) Recht auf Leben (Artikel 2),  (ii) Verbot der Folter und unmenschlicher oder erniedrigender Behandlung (Artikel 3),  (iii) Recht auf Freiheit und Sicherheit (Artikel 5),  (iv) Recht auf ein faires Verfahren (Artikel 6),  (v) Achtung des Privat- und Familienlebens (Artikel 8),  (vi) Recht auf Gedanken-, Gewissens- und Religionsfreiheit (Artikel 9),  (vii) Meinungsfreiheit (Artikel 10), sowie (viii) Versammlungs- und Vereinigungsfreiheit (Artikel 11)"}, {"kategorie": "", "text": "Der Europäische Gerichtshof für Menschenrechte (EGMR) in Straßburg überwacht die Einhaltung der EMRK durch die Mitgliedstaaten. Jede Person, die glaubt, dass ihre Rechte aus der EMRK verletzt wurden, kann nach Ausschöpfung des nationalen Rechtswegs eine Beschwerde beim EGMR einreichen"}, {"kategorie": "", "text": "Die EMRK prägt das österreichische Rechtssystem entscheidend und dient als Maßstab für die Überprüfung von [[Gesetzen]] und staatlichen Maßnahmen in Bezug auf ihre Vereinbarkeit mit den Menschenrechten."}]'::jsonb, ''),
  ('grund-und-menschenrechte', 'Grund- und Menschenrechte', '', '', '', '', 'Grund- und Menschenrechte', '[{"kategorie": "pol.", "text": "\"fundamentale Rechte, die jeder Person zustehen und die vor staatlichen Eingriffen schützen\""}, {"kategorie": "", "text": "Die Grund- und Menschenrechte sind in der österreichischen [[Verfassung]] verankert und gewährleisten persönliche Freiheiten, politische Partizipation sowie soziale und wirtschaftliche Sicherheit\""}, {"kategorie": "", "text": "Diese Rechte basieren sowohl auf nationalen als auch internationalen Rechtsquellen und bilden eine wesentliche Grundlage für die österreichische [[Rechtsstaatlichkeit]] und [[Demokratie]]"}, {"kategorie": "", "text": "Die Grund- und Menschenrechte sind durch die österreichische [[Bundesverfassung]] sowie durch internationale Abkommen, insbesondere die [[Europäische]] Menschenrechtskonvention (EMRK), geschützt. Die EMRK hat in Österreich Verfassungsrang und spielt eine zentrale Rolle beim Schutz der Menschenrechte. Diese Rechte gelten als unantastbar und müssen von allen staatlichen Institutionen respektiert und gewährleistet werden"}, {"kategorie": "", "text": "Zu den wichtigsten Grundrechten in Österreich gehören: (i) Recht auf Leben (der Staat muss das Leben jedes Menschen schützen, und Todesstrafe ist in Österreich verfassungsrechtlich verboten),  (ii) Recht auf persönliche Freiheit (niemand darf ohne rechtlichen Grund seiner Freiheit beraubt werden),  (iii) Gleichheit vor dem Gesetz: (alle Menschen sind vor dem [[Gesetz]] gleich und dürfen nicht aufgrund von Geschlecht, Herkunft, Religion oder anderen Merkmalen diskriminiert werden),  (iv) [[Meinungsfreiheit]] (jeder hat das Recht, seine Meinung frei zu äußern, sei es durch Wort, Schrift oder Bild, solange dies nicht die Rechte anderer verletzt),  (v) [[Versammlungsfreiheit]] (Bürger dürfen sich versammeln und Proteste oder öffentliche Veranstaltungen abhalten, ohne dass der Staat dies unbegründet einschränken darf),  (vi) [[Religionsfreiheit]] (jeder hat das Recht, seine Religion frei zu wählen und auszuüben, ebenso wie das Recht, keiner Religion anzugehören),  (vii) Recht auf Privat- und Familienleben (der Schutz der Privatsphäre, der Wohnung und des Familienlebens ist ein zentrales Recht)."}]'::jsonb, ''),
  ('oestarreichischa-schdood', 'Östarreichischa Schdood', '', '', '', '', 'Österreichischer Staat', '[{"kategorie": "pol.", "text": "\" föderaler, demokratischer und sozialer [[Rechtsstaat]], der durch seine [[Verfassung]] geregelt ist\""}, {"kategorie": "", "text": "Der österreichische Staat ist eine demokratische Republik und ein Bundesstaat in Mitteleuropa, der auf den Prinzipien der [[Demokratie]], der [[Rechtsstaatlichkeit]] und der [[Gewaltenteilung]] beruht. Der Staat umfasst die politischen und rechtlichen Institutionen sowie die geografischen und gesellschaftlichen Strukturen, die das Gemeinwesen Österreichs bilden"}, {"kategorie": "", "text": "Österreich ist seit der Verfassung von 1920 eine demokratische Republik. Das bedeutet, dass alle [[Staatsgewalt]] vom Volk ausgeht und das Volk durch gewählte Vertreter in der Politik mitbestimmt. Die Österreichische [[Bundesverfassung]] bildet die Grundlage des Staates und regelt die politische und rechtliche Ordnung. Sie legt die [[Grundrechte]] der Bürger fest und beschreibt die Funktionsweise der [[Staatsorgane]]"}, {"kategorie": "", "text": "Österreich ist ein föderaler Staat, was bedeutet, dass es sich aus dem [[Bund]] und den neun [[Bundesländern]] zusammensetzt"}, {"kategorie": "", "text": "Der österreichische Staat basiert auf dem Prinzip der [[Gewaltenteilung]] zwischen [[Legislative]], [[Exekutive]] und [[Judikative]]"}, {"kategorie": "", "text": "Das Staatsoberhaupt des österreichischen Staates ist der [[Bundespräsident]], der alle sechs Jahre direkt vom Volk gewählt wird. Der Bundespräsident hat in erster Linie repräsentative Aufgaben, besitzt aber auch wichtige verfassungsrechtliche Befugnisse, wie die Ernennung des [[Bundeskanzlers]] und der [[Minister]] sowie das Recht, den [[Nationalrat]] aufzulösen"}, {"kategorie": "", "text": "Der österreichische Staat ist ein [[Rechtsstaat]], was bedeutet, dass alle staatlichen Handlungen auf der Grundlage von [[Gesetzen]] erfolgen müssen. Die Einhaltung der Gesetze wird durch unabhängige [[Gerichte]] überwacht, und die Bürger haben das Recht auf rechtlichen Schutz. Die [[Verfassung]] garantiert den Schutz der [[Grund-]] und Menschenrechte sowie die Freiheit des Einzelnen vor staatlicher Willkür"}, {"kategorie": "", "text": "Der österreichische Staat ist ein aktives Mitglied der internationalen Gemeinschaft und gehört Organisationen wie den Vereinten Nationen (UNO), der Europäischen Union (EU) und der Organisation für Sicherheit und Zusammenarbeit in Europa (OSZE) an"}, {"kategorie": "", "text": "Österreich vertritt eine neutrale Außenpolitik, was bedeutet, dass es sich verpflichtet hat, nicht an militärischen Bündnissen teilzunehmen. Die [[immerwährende]] Neutralität ist ein wesentlicher Bestandteil der Außenpolitik und wurde 1955 in der Verfassung verankert."}]'::jsonb, ''),
  ('politische-wueuensbueuedung', 'Politische Wüünsbüüdung', '', '', '', '', 'Politische Willensbildung', '[{"kategorie": "pol.", "text": "\"komplexer Prozess, bei dem verschiedene Akteure – [[Bürger]], [[politische]] Parteien, [[Interessensgruppen]], [[Medien]] und [[Zivilgesellschaften]] (NGOs) – gemeinsam zur Entstehung und Umsetzung politischer Entscheidungen beitragen\""}, {"kategorie": "", "text": "Wahlen und direktdemokratische Instrumente ([[Volksbegehren]], [[Volksabstimmung]], [[Volksbefragung]]) ermöglichen die Partizipation der Bürger, während politische Parteien, Interessenvertretungen und Medien als Vermittler und Organisatoren dieser Meinungsbildung fungieren"}, {"kategorie": "", "text": "Dieser Prozess garantiert, dass unterschiedliche gesellschaftliche Interessen und Meinungen berücksichtigt werden und in die politische Entscheidungsfindung einfließen."}]'::jsonb, ''),
  ('repraesentative-demokratii', 'Repräsentative Demokratii', '', '', '', '', 'Repräsentative Demokratie', '[{"kategorie": "pol.", "text": "\"politisches System, in dem die Bürger ihre politischen Entscheidungen nicht direkt treffen, sondern Volksvertreter wählen, die diese Entscheidungen im Namen der Bevölkerung treffen\""}, {"kategorie": "", "text": "In Österreich ist die repräsentative Demokratie der zentrale Pfeiler des politischen Systems, bei dem die Bürger ihre Vertreter in regelmäßigen Wahlen bestimmen, insbesondere auf nationaler, regionaler und kommunaler Ebene"}, {"kategorie": "", "text": "In Österreich wählen die Bürger alle fünf Jahre die Mitglieder des [[Nationalrats]], der das zentrale gesetzgebende Organ ist. Diese Wahlen sind allgemein, frei, gleich, unmittelbar und geheim, und alle österreichischen Staatsbürger ab 16 Jahren haben das Wahlrecht"}, {"kategorie": "", "text": "Neben dem Nationalrat gibt es auch Wahlen auf Landesebene zu den [[Landtagen]] der neun [[Bundesländer]] und zu den [[Gemeinderäten]] auf kommunaler Ebene. Diese gewählten Organe vertreten die Interessen der Bürger in ihren jeweiligen politischen Bereichen"}, {"kategorie": "", "text": "Die gewählten Vertreter im Nationalrat und in den Landtagen sind verantwortlich für die [[Gesetzgebung]]. Sie entscheiden über nationale [[Gesetze]] und politische Maßnahmen"}, {"kategorie": "", "text": "Der [[Bundesrat]], der die [[Bundesländer]] vertritt, spielt ebenfalls eine Rolle bei der Gesetzgebung, insbesondere wenn es um Gesetze geht, die die Interessen der Länder betreffen"}, {"kategorie": "", "text": "Die politischen Entscheidungen werden von den gewählten [[Abgeordneten]] im Namen der Bürger getroffen, und diese Volksvertreter sind an ihre Parteien, Programme und Wahlversprechen gebunden"}, {"kategorie": "", "text": "In der repräsentativen Demokratie Österreichs ist die [[Gewaltenteilung]] zwischen [[Legislative]] ([[Parlament]]), [[Exekutive]] ([[Regierung]]) und [[Judikative]] ([[Gerichte]]) ein zentrales Prinzip. Die gewählten Vertreter kontrollieren die Regierung und üben Gesetze aus, während die Gerichte über die Einhaltung der Gesetze wachen. Diese Trennung sorgt für ein System der gegenseitigen Kontrolle, um Machtmissbrauch zu verhindern"}, {"kategorie": "", "text": "[[Politische]] Parteien spielen in der repräsentativen Demokratie Österreichs eine entscheidende Rolle. Sie organisieren die politischen Interessen der Bürger, stellen Kandidaten für Wahlen auf und helfen bei der politischen Willensbildung."}]'::jsonb, ''),
  ('politische-ordnung', 'politische Ordnung', '', '', '', '', 'Politische Ordnung', '[{"kategorie": "pol.", "text": "\"System von Institutionen, Gesetzen und Regeln, das die politische Entscheidungsfindung und die Organisation in Österreich regelt\""}, {"kategorie": "", "text": "Sie basiert auf demokratischen Grundsätzen, der [[Gewaltenteilung]] sowie dem föderalen Aufbau des Landes ([[Föderalismus]])"}, {"kategorie": "", "text": "Die politische Ordnung definiert, wie die Macht im Staat verteilt ist und welche Rollen und Verantwortungen verschiedene Institutionen haben"}, {"kategorie": "", "text": "Österreich ist eine [[repräsentative]] Demokratie, in der das Volk durch regelmäßige Wahlen seine Vertreter wählt. Diese Volksvertreter üben die Gesetzgebungsfunktion im [[Parlament]] aus"}, {"kategorie": "", "text": "Die politische Ordnung beruht auf der [[Bundesverfassung]], welche die grundlegenden Rechte, die Struktur des Staates und die demokratischen Prozesse festlegt, sowie auf der klassischen [[Gewaltenteilung]] zwischen [[Legislative]], [[Exekutive]] und [[Judikative]]"}, {"kategorie": "", "text": "Österreich ist ein föderaler Staat, das heißt, es gibt neben der Bundesebene auch neun [[Bundesländer]] mit eigenen Gesetzgebungsorganen ([[Landtage]]) und Verwaltungen. Die bundesstaatliche Ordnung garantiert den Bundesländern einen eigenen Einflussbereich und sichert die regionale Autonomie in bestimmten Angelegenheiten"}, {"kategorie": "", "text": "Österreich hat ein parlamentarisches Regierungssystem. Der [[Bundeskanzler]] ist der [[Regierungschef]] und wird vom [[Bundespräsidenten]] auf Grundlage der Mehrheitsverhältnisse im [[Nationalrat]] ernannt"}, {"kategorie": "", "text": "Wahlen spielen eine zentrale Rolle in der politischen Ordnung. Auf Bundesebene wählen die Bürger den Nationalrat sowie den Bundespräsidenten. Auf Landes- und Gemeindeebene gibt es Wahlen zu den Landtagen und Gemeinderäten"}, {"kategorie": "", "text": "Ein zentrales Prinzip der politischen Ordnung ist die [[Rechtsstaatlichkeit]], das heißt, dass alle staatlichen Entscheidungen auf Grundlage von Gesetzen getroffen werden müssen. [[Gerichte]] überwachen, dass die Regierung und der Gesetzgeber die [[Verfassung]] und die [[Gesetze]] einhalten"}, {"kategorie": "", "text": "Eine Besonderheit der politischen Ordnung in Österreich ist die [[Sozialpartnerschaft]]. Sie umfasst die Zusammenarbeit von Arbeitgeberverbänden, Gewerkschaften, Kammern und der Regierung bei der Gestaltung von Wirtschafts- und Sozialpolitik. Diese Kooperation hat entscheidend zur politischen Stabilität und zum sozialen Frieden in Österreich beigetragen."}]'::jsonb, ''),
  ('seavas-tv', 'Seavas TV', '', '', '', '', 'Servus TV', '[{"kategorie": "allg.", "text": "\"österreichischer privater Fernsehsender, der 2009 gegründet wurde und zur Red Bull Media House GmbH, einem Tochterunternehmen des Red Bull-Konzerns, gehört\""}, {"kategorie": "", "text": "ServusTV hat seinen Sitz in Salzburg und bietet ein vielfältiges Programm, das sich auf Nachrichten, Dokumentationen, Unterhaltung, Sport und Kultur konzentriert"}, {"kategorie": "", "text": "Der Sender hat sich durch hochwertige Inhalte und Eigenproduktionen einen Namen gemacht und legt besonderen Wert auf anspruchsvolle Berichterstattung sowie österreichische und internationale Themen"}, {"kategorie": "", "text": "ServusTV hat sich in der [[österreichischen]] Medienlandschaft als qualitativ hochwertiger Privatsender etabliert, der ein breites Spektrum an Nachrichten, Dokumentationen, Sport und Kultur anbietet."}]'::jsonb, ''),
  ('puls-4', 'Puls 4', '', '', '', '', 'Puls 4', '[{"kategorie": "allg.", "text": "\"österreichischer privater Fernsehsender, der 2008 gegründet wurde und zur ProSiebenSat.1 PULS 4 Gruppe gehört, einem der größten Medienkonzerne im deutschsprachigen Raum\""}, {"kategorie": "", "text": "Der Sender bietet ein breites Spektrum an Inhalten, darunter Nachrichten, Unterhaltung, Filme, Serien, Reality-TV und Sport"}, {"kategorie": "", "text": "Puls 4 hat sich zu einem wichtigen Akteur in der [[österreichischen]] Medienlandschaft entwickelt, insbesondere durch seine Nachrichtensendungen und politischen Diskussionsformate."}]'::jsonb, ''),
  ('oestarreichische-mediinlaundschoft', 'Östarreichische Mediinlaundschoft', '', '', '', '', 'Österreichische Medienlandschaft', '[{"kategorie": "allg.", "text": "\"Gesamtheit der Medien in Österreich, darunter [[Printmedien]], [[Rundfunk]] (Radio und Fernsehen), [[Online-Medien]] sowie soziale Netzwerke\""}, {"kategorie": "", "text": "Diese vielfältige Medienlandschaft spielt eine zentrale Rolle in der öffentlichen Meinungsbildung, politischen Kommunikation und kulturellen Identität des Landes. Sie besteht aus einer Mischung aus öffentlich-rechtlichen und privaten Medienanbietern"}, {"kategorie": "", "text": "Der [[ORF]] (Österreichischer Rundfunk) ist die bedeutendste öffentlich-rechtliche Medienorganisation in Österreich und bietet Radio- und Fernsehsendungen sowie Online-Inhalte an"}, {"kategorie": "", "text": "Neben dem ORF gibt es zahlreiche private Medienunternehmen in Österreich. Dazu gehören private Fernsehsender, Radiostationen, Zeitungen und Online-Plattformen. Große Medienhäuser wie die Mediengruppe Österreich, Styria Media Group und das Red Bull Media House besitzen mehrere Medienangebote und sind wichtige Akteure auf dem Markt. Die größten privaten Fernsehsender sind [[Puls]] 4, [[ATV]] und [[ServusTV]], die sowohl Unterhaltungs- als auch Nachrichtenformate anbieten"}, {"kategorie": "", "text": "Österreich hat eine starke Printmedien-Tradition, mit einer breiten Auswahl an Tageszeitungen, Wochenzeitungen und Magazinen. Zu den bekanntesten nationalen Tageszeitungen gehören: (i) [[Kronen]] Zeitung (die auflagenstärkste Boulevardzeitung),  (ii) [[Der]] Standard (liberal),  (iii) [[Die]] Presse (konservativ),  (iv) Kurier (zentristisch)"}, {"kategorie": "", "text": "Die Digitalisierung hat die Medienlandschaft stark verändert, und viele traditionelle Medienunternehmen haben Online-Portale entwickelt, um mit dem Wandel Schritt zu halten. Nachrichtenplattformen wie derstandard.at, orf.at und heute.at haben eine breite Leserschaft, während unabhängige Online-Medien wie addendum.org oder zackzack.at zunehmend an Bedeutung gewinnen"}, {"kategorie": "", "text": "Die [[Pressefreiheit]] ist in Österreich verfassungsrechtlich garantiert und wird durch verschiedene Gesetze wie das Mediengesetz geschützt"}, {"kategorie": "", "text": "Die österreichische Medienlandschaft zeichnet sich durch eine Mischung aus traditionellen Printmedien, öffentlich-rechtlichem Rundfunk und einer wachsenden Zahl digitaler Plattformen aus. Sie spielt eine zentrale Rolle in der Meinungsbildung, der [[Demokratie]] und der politischen Transparenz."}]'::jsonb, ''),
  ('oestarreichische-gsoeschoft', 'Östarreichische Gsöschoft', '', '', '', '', 'Österreichische Gesellschaft', '[{"kategorie": "pol.", "text": "\"Gesamtheit der Menschen, die in einem gemeinsamen sozialen, politischen, wirtschaftlichen und kulturellen Rahmen in Österreich zusammenleben\""}, {"kategorie": "", "text": "Sie ist geprägt von historischen Entwicklungen, kulturellen Traditionen und einer gemeinsamen rechtlichen und politischen Ordnung"}, {"kategorie": "", "text": "Die österreichische Gesellschaft ist vielfältig und setzt sich aus verschiedenen sozialen Gruppen und Gemeinschaften zusammen, die durch gemeinsame Werte, Normen und Strukturen verbunden sind"}, {"kategorie": "", "text": "Die österreichische Gesellschaft ist stark von ihrer kulturellen Vielfalt geprägt. Österreich hat eine lange Geschichte als multikultureller Staat, besonders in den Städten wie Wien, wo Menschen unterschiedlicher Herkunft und Religion zusammenleben"}, {"kategorie": "", "text": "Der Einfluss der Geschichte, insbesondere der [[Habsburgermonarchie]], hat eine pluralistische und kosmopolitische Gesellschaft geformt. Kulturelle Institutionen wie Theater, Musik und Kunst haben eine zentrale Rolle in der österreichischen Identität."}]'::jsonb, ''),
  ('politischa-diskuas', 'Politischa Diskuas', '', '', '', '', 'Politischer Diskurs', '[{"kategorie": "pol.", "text": "\"Austausch von Meinungen, Argumenten und Ideen zu politischen Themen innerhalb einer [[Gesellschaft]]\""}, {"kategorie": "", "text": "Er umfasst Diskussionen über politische Entscheidungen, Gesetze, Werte und gesellschaftliche Fragen, die in verschiedenen Foren wie Parlamenten, Medien, öffentlichen Debatten oder sozialen Netzwerken geführt werden"}, {"kategorie": "", "text": "In [[demokratischen]] Gesellschaften ist der politische Diskurs ein wichtiges Mittel zur politischen Teilhabe. Bürger können ihre Meinungen äußern, sich informieren und sich an der politischen Willensbildung beteiligen"}, {"kategorie": "", "text": "[[Medien]] spielen ebenfalls eine entscheidende Rolle im politischen Diskurs, indem sie Informationen verbreiten, Diskussionen anregen und Plattformen für den Austausch bieten"}, {"kategorie": "", "text": "Ziel des politischen Diskurses ist es, durch Debatten und Argumentation Entscheidungen zu treffen, die im besten Interesse der Gesellschaft sind.\nDabei geht es nicht nur um den Austausch von Meinungen, sondern auch um die Aushandlung von Kompromissen und das Erreichen von Lösungen für politische und gesellschaftliche Probleme."}]'::jsonb, ''),
  ('parlamentarisches-system', 'Parlamentarisches System', '', '', '', '', 'Parlamentarisches System', '[{"kategorie": "pol.", "text": "\"Regierungsform, in der das [[Parlament]] als zentrale Institution des Staates fungiert\""}, {"kategorie": "", "text": "In Österreich ist das parlamentarische System fest in der [[Bundesverfassung]] verankert und bildet das Herzstück der [[österreichischen]] Demokratie. Dabei gibt es eine enge Verzahnung zwischen der [[Legislative]] (Parlament) und der [[Exekutive]] (Regierung)"}, {"kategorie": "", "text": "Österreich hat ein Zweikammernsystem, bestehend aus dem [[Nationalrat]] und dem [[Bundesrat]]. Der Nationalrat ist das Hauptorgan der [[Gesetzgebung]] und wird direkt vom Volk gewählt. Er kontrolliert die Regierung und hat das Recht, diese durch ein [[Misstrauensvotum]] zu entlassen. Der Bundesrat vertritt die Länder auf Bundesebene und hat in vielen Fällen ein Mitspracherecht, insbesondere bei Gesetzen, die die Kompetenzen der Länder betreffen"}, {"kategorie": "", "text": "Im parlamentarischen System Österreichs ist die Regierung (die Exekutive) vom Vertrauen des Parlaments abhängig, insbesondere vom Nationalrat. Der [[Bundeskanzler]], der [[Regierungschef]], und die [[Minister]] müssen das Vertrauen der Mehrheit im Nationalrat genießen, um ihre Ämter auszuüben. Ein Misstrauensvotum durch den Nationalrat kann zum Rücktritt der Regierung führen. Die Regierung ist dem Nationalrat rechenschaftspflichtig und muss regelmäßig über ihre Arbeit berichten"}, {"kategorie": "", "text": "Obwohl es eine formale [[Gewaltenteilung]] zwischen der Legislative (Parlament) und der Exekutive (Regierung) gibt, arbeiten beide eng zusammen. Die Regierung bringt häufig [[Gesetzesvorschläge]] in den [[Nationalrat]] ein, der dann über deren Annahme oder Ablehnung entscheidet. Zudem beeinflusst die [[Parlamentsmehrheit]] die Regierung direkt, da die Regierungsmitglieder in der Regel aus der [[Mehrheitsfraktion]] des Nationalrats kommen"}, {"kategorie": "", "text": "Der Nationalrat wird alle fünf Jahre in allgemeinen, gleichen, freien, direkten und geheimen Wahlen gewählt. Die Zusammensetzung des Parlaments spiegelt also den politischen Willen der Bevölkerung wider. Die Wahlen haben direkte Auswirkungen auf die Zusammensetzung der Regierung, da diese auf der Mehrheit im Nationalrat basiert"}, {"kategorie": "", "text": "Der [[Bundespräsident]] hat eine wichtige Rolle im parlamentarischen System Österreichs, da er den [[Bundeskanzler]] ernennt und die Regierung formal entlassen kann. Allerdings spielt er überwiegend eine repräsentative Rolle und greift nur selten aktiv in das politische Tagesgeschäft ein.\nIn Ausnahmefällen kann der Bundespräsident auch das Parlament auflösen, was jedoch selten vorkommt"}, {"kategorie": "", "text": "Das [[Parlament]], insbesondere der Nationalrat, hat eine wichtige Kontrollfunktion gegenüber der Regierung. Dies geschieht durch [[parlamentarische]] Anfragen, [[Untersuchungsausschüsse]] und [[Misstrauensvoten]]. Auch die [[Opposition]] spielt im parlamentarischen System eine zentrale Rolle, da sie die [[Regierung]] hinterfragt und alternative Vorschläge einbringt."}]'::jsonb, ''),
  ('oestarreichische-justiz', 'Östarreichische Justiz', '', '', '', '', 'Österreichische Justiz', '[{"kategorie": "pol.", "text": "\"die rechtsprechende Gewalt des Staates und eine der drei Säulen der [[Gewaltenteilung]] neben der [[Legislative]] (gesetzgebende Gewalt) und der [[Exekutive]] (ausführende Gewalt)\""}, {"kategorie": "", "text": "Die Judikative ist dafür verantwortlich, Gesetze anzuwenden und über Streitfälle zu entscheiden. Ihre Hauptaufgabe ist es, die Einhaltung der Gesetze zu überwachen und sicherzustellen, dass diese korrekt interpretiert und durchgesetzt werden"}, {"kategorie": "", "text": "Die Justiz ist in Österreich unabhängig von der [[Regierung]] und dem Parlament. Das bedeutet, dass [[Gerichte]] und [[Richter]] nicht in ihrer Entscheidungsfindung durch andere Staatsorgane beeinflusst werden dürfen. Diese Unabhängigkeit ist durch die österreichische [[Bundesverfassung]] garantiert"}, {"kategorie": "", "text": "Die Judikative spielt eine zentrale Rolle in der [[Rechtsstaatlichkeit]] Österreichs, indem sie sicherstellt, dass die Gesetze des Landes korrekt angewendet werden und die Rechte der Bürger geschützt sind"}, {"kategorie": "", "text": "Zusammengefasst ist die Judikative in Österreich das System der [[Gerichte]], das für die Durchsetzung der Gesetze, die [[Rechtsprechung]] und den Schutz der Verfassung verantwortlich ist​."}]'::jsonb, ''),
  ('oestarreisches-voik', 'Östarreisches Voik', '', '', '', '', 'Österreichisches Volk', '[{"kategorie": "pol.", "text": "\"alle Staatsbürgerinnen und Staatsbürger der Republik Österreich\""}, {"kategorie": "", "text": "Das österreichische Volk bildet die Grundlage der staatlichen Souveränität und hat als Träger der [[Staatsgewalt]] ein Mitspracherecht in der Gestaltung des politischen und rechtlichen Systems des Landes"}, {"kategorie": "", "text": "Das österreichische Volk ist durch gemeinsame Rechte und Pflichten, eine gemeinsame [[Verfassung]] und die Teilnahme am demokratischen Leben des Staates verbunden"}, {"kategorie": "", "text": "Merkmale des österreichischen Volkes:  (i) [[Staatsbürgerschaft]]: Zum österreichischen Volk gehören alle Personen, die die österreichische Staatsbürgerschaft besitzen. Diese Staatsbürgerschaft ist Grundlage für die politischen Rechte und Pflichten, die dem Einzelnen als Mitglied der österreichischen Gemeinschaft zukommen;  (ii) Träger der Staatsgewalt: In der österreichischen [[Verfassung]] (Bundes-Verfassungsgesetz, Art. 1) ist festgelegt, dass alle [[Staatsgewalt]] vom [[Volk]] ausgeht. Dies bedeutet, dass das österreichische Volk über Wahlen und direktdemokratische Instrumente wie [[Volksabstimmungen]], [[Volksbefragungen]] und [[Volksbegehren]] an der politischen Willensbildung teilnimmt;  (iii) Demokratische Rechte und Pflichten: Staatsbürgerinnen und Staatsbürger haben das Recht, an Wahlen auf kommunaler, Landes- und Bundesebene teilzunehmen, sowie das Recht auf freie Meinungsäußerung, Versammlungsfreiheit und Mitbestimmung im Rahmen der demokratischen Ordnung. Gleichzeitig haben sie Pflichten, wie die Steuerzahlung und, für Männer, die Pflicht zum Wehr- oder Zivildienst (sofern nicht ausgesetzt);  (iv) Vielfalt und Integration: Das österreichische Volk ist ethnisch, kulturell und sprachlich vielfältig. Österreich fördert die Integration und das Zusammenleben verschiedener Volksgruppen und Minderheiten, etwa der slowenischen, kroatischen und ungarischen Minderheiten, die in der Verfassung anerkannt sind;  (v) Identität und Zugehörigkeit: Das österreichische Volk teilt eine gemeinsame kulturelle und historische Identität, die durch die Sprache, Traditionen und das Bewusstsein der gemeinsamen Geschichte geprägt ist. Diese Identität bildet die Grundlage für das nationale Zusammengehörigkeitsgefühl und den sozialen Zusammenhalt"}, {"kategorie": "", "text": "Das österreichische Volk ist somit die zentrale Grundlage des österreichischen Staates und verkörpert dessen demokratische und rechtsstaatliche Prinzipien. Es bestimmt durch seine Willensäußerungen und demokratische Beteiligung die politische Ausrichtung des Landes."}]'::jsonb, ''),
  ('parlamentarische-demokratii', 'Parlamentarische Demokratii', '', '', '', '', 'Parlamentarische Demokratie', '[{"kategorie": "pol.", "text": "\"Regierungssystem, in dem das Parlament das zentrale Organ der politischen Entscheidungsfindung ist und die [[Regierung]] von der Mehrheit des [[Parlaments]] abhängig ist\""}, {"kategorie": "", "text": "In Österreich bedeutet dies, dass die [[Legislative]] (der [[Nationalrat]] und der [[Bundesrat]]) im Zentrum der [[Staatsgewalt]] steht und dass die [[Exekutive]] (die [[Bundesregierung]]) nur so lange im Amt bleibt, wie sie das Vertrauen der Mehrheit im Nationalrat genießt"}, {"kategorie": "", "text": "Merkmale der parlamentarischen Demokratie in Österreich:  (i) Direkt gewähltes Parlament: In Österreich wird das Parlament (vor allem der Nationalrat) direkt von den Bürgerinnen und Bürgern gewählt. Der Nationalrat repräsentiert das Volk und ist das wichtigste gesetzgebende Organ des Landes;  (ii) Abhängigkeit der Regierung vom Parlament: Die Bundesregierung, bestehend aus dem [[Bundeskanzler]] und den [[Ministern]], muss vom Nationalrat gewählt werden und kann durch ein [[Misstrauensvotum]] jederzeit abgesetzt werden. Dadurch ist die Exekutive an die Legislative gebunden und auf deren Vertrauen angewiesen;  (iii) Kontrollfunktion des Parlaments: Der Nationalrat hat eine umfassende Kontrollfunktion über die Regierung. Er kann [[Untersuchungsausschüsse]] einsetzen, Anfragen an die Minister stellen und die Umsetzung von Gesetzen überprüfen;  (iv) Staatsoberhaupt mit begrenzter Macht: In Österreich ist der [[Bundespräsident]] das formale Staatsoberhaupt, hat aber in der Praxis überwiegend repräsentative Aufgaben. Die eigentliche politische Macht liegt beim Bundeskanzler und der Regierung, die durch das Parlament legitimiert sind;  (v) Gewaltenteilung und Rechtsstaatlichkeit: Die parlamentarische Demokratie in Österreich ist auf der Basis von [[Gewaltenteilung]] und [[Rechtsstaatlichkeit]] aufgebaut, was bedeutet, dass die Regierung und das Parlament an die Gesetze gebunden sind und die Gerichte die Einhaltung dieser Gesetze überwachen;  (vi) Beteiligung der Länder: Da Österreich ein föderaler Staat ist, spielen auch die [[Bundesländer]] eine Rolle in der Gesetzgebung. Der [[Bundesrat]] vertritt die Länderinteressen und kann bei [[Bundesgesetzen]] mitwirken, wenngleich der Nationalrat das Hauptgesetzgebungsorgan bleibt"}, {"kategorie": "", "text": "In der parlamentarischen Demokratie Österreichs liegt die politische Entscheidungsgewalt beim [[Parlament]], das die Interessen des [[Volkes]] vertritt. Durch die Abhängigkeit der Regierung vom Vertrauen des Parlaments und die umfassende Kontrollfunktion wird die Demokratie gestärkt und die Bürgernähe der politischen Entscheidungen sichergestellt."}]'::jsonb, ''),
  ('direkte-demokratii', 'Direkte Demokratii', '', '', '', '', 'Direkte Demokratie', '[{"kategorie": "pol.", "text": "\"politisches System oder Elemente eines Systems, in dem Bürgerinnen und Bürger unmittelbar an politischen Entscheidungen beteiligt sind, ohne ausschließlich über gewählte Vertreter zu entscheiden\""}, {"kategorie": "", "text": "Im Rahmen der direkten Demokratie können die Menschen durch Abstimmungen oder Initiativen direkt Einfluss auf Gesetze und politische Entscheidungen nehmen"}, {"kategorie": "", "text": "Merkmale der direkten Demokratie in Österreich:  (i) [[Volksabstimmung]] (bei einer Volksabstimmung stimmen die Bürgerinnen und Bürger über einen konkreten [[Gesetzesvorschlag]] oder eine [[Verfassungsänderung]] ab. Das Ergebnis ist rechtlich bindend und muss von der [[Regierung]] umgesetzt werden);  (ii) [[Volksbegehren]] (Instrument, mit dem Bürgerinnen und Bürger den [[Nationalrat]] auffordern können, sich mit einem bestimmten Anliegen oder [[Gesetzesvorschlag]] zu beschäftigen. Bei Erreichen einer festgelegten Anzahl an Unterschriften muss das Anliegen im Nationalrat behandelt werden, allerdings ist die Umsetzung nicht zwingend);  (iii) [[Volksbefragung]] (=konsultative Abstimmung zu einer politischen Frage. Sie hat einen beratenden Charakter und ist nicht bindend; das Ergebnis dient als Meinungsbild für die politischen Entscheidungsträger)"}, {"kategorie": "", "text": "Direkte Demokratie stärkt die politische Teilhabe und Mitbestimmung der Bevölkerung, da die Bürger direkt in wichtige Entscheidungsprozesse eingebunden werden"}, {"kategorie": "", "text": "In Österreich ergänzt die direkte Demokratie das repräsentative System und gibt der Bevölkerung die Möglichkeit, Einfluss auf zentrale politische Fragen zu nehmen."}]'::jsonb, '')
